      end

      T::Sig::WithoutRuntime.sig { returns(T::Boolean) }
      def index?
        admin?
      end

      T::Sig::WithoutRuntime.sig { returns(T::Boolean) }
      def show?
        admin?
      end

      T::Sig::WithoutRuntime.sig { returns(T::Boolean) }
      def edit?
        admin?
      end

      T::Sig::WithoutRuntime.sig { returns(T::Boolean) }
      def update?
        admin?
      end

      T::Sig::WithoutRuntime.sig { returns(T::Boolean) }
      def manage_roles?
        admin?
      end

      relation_scope do |relation|
        admin? ? relation : relation.none
      end
    end
  RUBY

