  create_file "test/models/user_role_test.rb", <<~RUBY, force: true
    require "test_helper"

    class UserRoleTest < ActiveSupport::TestCase
      test "grants admin when no administrator exists in development" do
        with_rails_environment("development") do
          User.destroy_all

          user = T.let(nil, T.nilable(User))
          assert_difference("UserRole.count", 1) { user = User.create! }

          assert T.must(user).has_role?(:admin)
        end
      end

      test "does not grant admin when an administrator already exists in development" do
        with_rails_environment("development") do
          User.destroy_all
          administrator = User.create!
          assert administrator.has_role?(:admin)

          later_user = T.let(nil, T.nilable(User))
          assert_no_difference("UserRole.count") { later_user = User.create! }

          assert_not T.must(later_user).has_role?(:admin)
        end
      end

      test "skips sample users and grants admin to the next created user" do
        with_rails_environment("development") do
          User.destroy_all
          sample_users = 10.times.map { User.create!(skip_initial_admin_role: true) }

          assert sample_users.none? { |user| user.has_role?(:admin) }
          assert_equal 10, User.count
          assert_equal 0, UserRole.admin.count

          signed_up_user = User.create!
          assert signed_up_user.has_role?(:admin)
          assert_equal 1, UserRole.admin.count
        end
      end

      test "does not grant initial admin outside development" do
        %w[test production].each do |environment_name|
          with_rails_environment(environment_name) do
            User.destroy_all

            user = T.let(nil, T.nilable(User))
            assert_no_difference("UserRole.count") { user = User.create! }

            assert_not T.must(user).has_role?(:admin)
          end
        end
      end

      test "rejects invalid and duplicate roles" do
        user = users(:one)
        invalid = user.user_roles.build(role: "unknown")

        assert_not invalid.valid?
        user.grant_role!(:admin)
        duplicate = user.user_roles.build(role: :admin)
        assert_not duplicate.valid?
      end

      test "grants a role idempotently" do
        user = users(:one)

        assert_difference("UserRole.count", 1) { user.grant_role!(:admin) }
        assert_no_difference("UserRole.count") { user.grant_role!(:admin) }
        assert user.has_role?(:admin)
      end

      test "database constraints reject invalid duplicate and null roles" do
        user = users(:one)
        now = Time.current
        user.grant_role!(:admin)

        # These writes intentionally bypass model validations to exercise database constraints.
        # rubocop:disable Rails/SkipsModelValidations
        assert_raises(ActiveRecord::StatementInvalid) do
          UserRole.insert_all!([{ user_id: user.id, role: "admin", created_at: now, updated_at: now }])
        end
        assert_raises(ActiveRecord::StatementInvalid) do
          UserRole.insert_all!([{ user_id: users(:two).id, role: "unknown", created_at: now, updated_at: now }])
        end
        assert_raises(ActiveRecord::NotNullViolation) do
          UserRole.insert_all!([{ user_id: users(:two).id, role: nil, created_at: now, updated_at: now }])
        end
        # rubocop:enable Rails/SkipsModelValidations
      end

      test "does not remove the final admin assignment" do
        user = users(:one)
        user.grant_role!(:admin)

        assert_raises(ActiveRecord::RecordNotDestroyed) { user.revoke_role!(:admin) }
        assert user.reload.has_role?(:admin)
        assert_not user.destroy
      end

      test "removes an admin when another admin remains" do
        first = users(:one)
        second = users(:two)
        first.grant_role!(:admin)
        second.grant_role!(:admin)

        assert first.revoke_role!(:admin)
        assert_not first.reload.has_role?(:admin)
        assert second.reload.has_role?(:admin)
      end

      test "destroys assignments with a non-final admin user" do
        first = users(:one)
        second = users(:two)
        first.grant_role!(:admin)
        second.grant_role!(:admin)
        role_id = first.user_roles.find_by!(role: :admin).id

        assert first.destroy
        assert_not UserRole.exists?(role_id)
      end

      private
        def with_rails_environment(environment)
          previous_environment = Rails.env
          Rails.env = environment
          yield
        ensure
          Rails.env = previous_environment
        end
    end
  RUBY

  create_file "test/policies/user_policy_test.rb", <<~RUBY, force: true
    require "test_helper"

    class UserPolicyTest < ActiveSupport::TestCase
      test "allows admins and denies regular users" do
        admin = users(:one)
        regular = users(:two)
        admin.grant_role!(:admin)

        assert UserPolicy.new(User, user: admin).apply(:overview?)
        assert UserPolicy.new(User, user: admin).apply(:index?)
        assert UserPolicy.new(regular, user: admin).apply(:show?)
        assert UserPolicy.new(regular, user: admin).apply(:edit?)
        assert UserPolicy.new(regular, user: admin).apply(:update?)
        assert UserPolicy.new(regular, user: admin).apply(:manage_roles?)
        assert_not UserPolicy.new(User, user: regular).apply(:overview?)
        assert_not UserPolicy.new(User, user: regular).apply(:index?)
        assert_not UserPolicy.new(admin, user: regular).apply(:show?)
        assert_not UserPolicy.new(admin, user: regular).apply(:edit?)
        assert_not UserPolicy.new(admin, user: regular).apply(:update?)
        assert_not UserPolicy.new(admin, user: regular).apply(:manage_roles?)
      end

      test "scopes users to admins" do
        admin = users(:one)
        regular = users(:two)
        admin.grant_role!(:admin)

        assert_equal User.all, UserPolicy.new(User, user: admin).apply_scope(User.all, type: :active_record_relation)
        assert_empty UserPolicy.new(User, user: regular).apply_scope(User.all, type: :active_record_relation)
      end
    end
  RUBY

