  create_file "app/controllers/notifications_controller.rb", <<~RUBY, force: true
    class NotificationsController < ApplicationController
      extend T::Sig

      TABS = %w[personal announcements].freeze
      ANNOUNCEMENT_SURFACES = %w[history popover].freeze

      before_action :authenticate_user!
      before_action :set_tab, only: %i[index popover]

      sig { void }
      def index
        @surface = "history"
        @cutoff = Time.current
        if @tab == "personal"
          @pagy, @deliveries = pagy(:offset, deliveries_scope(@cutoff), limit: 25)
        else
          @pagy, @announcements = pagy(:offset, announcements_scope(@cutoff), limit: 25)
        end
      end

      sig { void }
      def popover
        @surface = "popover"
        @cutoff = Time.current
        if @tab == "personal"
          @deliveries = deliveries_scope(@cutoff).limit(10)
        else
          @announcements = announcements_scope(@cutoff).limit(10)
        end
        render layout: false
      end

      sig { void }
      def open
        @delivery = deliveries_scope.find_by!(notification_id: params.expect(:id))
        allowed_frames = %W[
          popover_personal_notification_\#{@delivery.notification_id}
          history_personal_notification_\#{@delivery.notification_id}
        ]
        @origin_frame = params.expect(:origin_frame)
        raise ActionController::BadRequest unless allowed_frames.include?(@origin_frame)

        @personal_status_target = @origin_frame.start_with?("popover_") ?
          "popover_personal_unread_status" : "history_personal_unread_status"
        @delivery.open!
      end

      sig { void }
      def open_all
        @origin_frame = params.expect(:origin_frame)
        raise ActionController::BadRequest unless @origin_frame == "notifications_popover"

        # rubocop:disable Rails/SkipsModelValidations -- 現在Userの公開済み未読だけを一括更新する
        deliveries_scope.where(opened_at: nil).update_all(opened_at: Time.current, updated_at: Time.current)
        # rubocop:enable Rails/SkipsModelValidations
        @tab = "personal"
        @surface = "popover"
        @cutoff = Time.current
        @deliveries = deliveries_scope(@cutoff).limit(10)
      end

      sig { void }
      def read_announcements
        @surface = params.expect(:surface)
        raise ActionController::BadRequest unless ANNOUNCEMENT_SURFACES.include?(@surface)

        @cutoff = Time.zone.iso8601(params.expect(:cutoff))
        raise ActionController::BadRequest if @cutoff > Time.current

        T.must(current_user).mark_announcements_read_through!(cutoff: @cutoff)
      rescue ActiveRecord::ActiveRecordError
        @read_failed = true
        render :read_announcements, status: :unprocessable_content
      rescue ArgumentError
        raise ActionController::BadRequest
      end

      private
        sig { void }
        def set_tab
          @tab = params.fetch(:tab, "personal")
          raise ActionController::BadRequest unless TABS.include?(@tab)
        end

        sig { params(cutoff: T.any(Time, ActiveSupport::TimeWithZone)).returns(ActiveRecord::Relation) }
        def deliveries_scope(cutoff = Time.current)
          T.must(current_user).notification_deliveries.published(cutoff).ordered.includes(
            notification: { rich_text_message: { embeds_attachments: :blob } }
          )
        end

        sig { params(cutoff: T.any(Time, ActiveSupport::TimeWithZone)).returns(ActiveRecord::Relation) }
        def announcements_scope(cutoff)
          Notification.published(cutoff).announcements.ordered.with_rich_text_message_and_embeds
        end
    end
  RUBY

  create_file "app/controllers/admin/notifications_controller.rb", <<~RUBY, force: true
    module Admin
      class NotificationsController < BaseController
        extend T::Sig

        before_action :set_notification, only: %i[show edit update destroy]

        sig { void }
        def index
          authorize! Notification, to: :index?
          notifications = authorized_scope(Notification.all)
            .with_rich_text_message_and_embeds
            .includes(:notification_deliveries)
            .order(published_at: :desc, id: :desc)
          @pagy, @notifications = pagy(:offset, notifications, limit: 25)
        end

        sig { void }
        def show
          authorize! @notification
        end

        sig { void }
        def new
          @notification = Notification.new(draft: true, published_at: Time.current, audience: :all_users)
          authorize! @notification
          @recipient_ids = []
        end

        sig { void }
        def edit
          authorize! @notification, to: :update?
          @recipient_ids = @notification.notification_deliveries.pluck(:user_id)
        end

        sig { void }
        def create
          @notification = Notification.new(notification_attributes)
          authorize! @notification
          @recipient_ids = recipient_ids
          @notification.save_with_delivery_synchronization!(recipient_ids: @recipient_ids)
          redirect_to admin_notification_path(@notification), notice: t("notifications.admin.created"), status: :see_other
        rescue ActiveRecord::RecordInvalid, ActiveRecord::RecordNotFound
          render :new, status: :unprocessable_content
        end

        sig { void }
        def update
          authorize! @notification
          @recipient_ids = recipient_ids
          @notification.assign_attributes(notification_attributes)
          @notification.save_with_delivery_synchronization!(recipient_ids: @recipient_ids)
          redirect_to admin_notification_path(@notification), notice: t("notifications.admin.updated"), status: :see_other
        rescue ActiveRecord::RecordInvalid, ActiveRecord::RecordNotFound
          render :edit, status: :unprocessable_content
        end

        sig { void }
        def destroy
          authorize! @notification
          @notification.destroy!
          redirect_to admin_notifications_path, notice: t("notifications.admin.destroyed"), status: :see_other
        end

        private
          sig { void }
          def set_notification
            @notification = Notification.find(params.expect(:id))
          end

          def notification_attributes
            params.expect(notification: %i[message audience published_at draft])
          end

          sig { returns(T::Array[Integer]) }
          def recipient_ids
            Array(params.dig(:notification, :recipient_ids)).compact_blank.map { |value| Integer(value, 10) }.uniq
          end
      end
    end
  RUBY

  create_file "app/controllers/admin/notification_recipients_controller.rb", <<~RUBY, force: true
    module Admin
      class NotificationRecipientsController < BaseController
        extend T::Sig

        sig { void }
        def index
          authorize! Notification, to: :search_recipients?
          query = params[:q].to_s.strip
          @selected_ids = Array(params[:selected_ids]).compact_blank.map { |value| Integer(value, 10) }
          like_query = "%\#{ActiveRecord::Base.sanitize_sql_like(query)}%"
          @users = if query.present?
            User.joins(:profile)
              .where("profiles.display_name LIKE :query", query: like_query)
              .where.not(id: @selected_ids)
              .order("profiles.display_name ASC", "users.id ASC")
              .limit(20)
          else
            User.none
          end
        end
      end
    end
  RUBY

