  create_file "app/javascript/controllers/notification_popover_controller.js", <<~JAVASCRIPT, force: true
    import { Controller } from "@hotwired/stimulus"

    export default class extends Controller {
      static targets = ["frame", "error"]
      static values = { url: String }

      load(event) {
        if (event.newState !== "open") return

        const personalUrl = new URL(this.urlValue, window.location.origin).toString()
        this.frameTarget.removeAttribute("complete")
        if (this.frameTarget.src === personalUrl) {
          this.frameTarget.reload()
        } else {
          this.frameTarget.src = personalUrl
        }
      }

      retry() {
        this.frameTarget.replaceChildren()
        this.frameTarget.removeAttribute("complete")
        this.frameTarget.reload()
      }

      error(event) {
        event.preventDefault()
        const content = this.errorTarget.content.cloneNode(true)
        content.querySelector("[data-notification-load-error]").classList.add("alert-error", "alert-soft")
        this.frameTarget.replaceChildren(content)
      }
    }
  JAVASCRIPT

  create_file "app/javascript/controllers/notification_announcements_controller.js", <<~JAVASCRIPT, force: true
    import { Controller } from "@hotwired/stimulus"

    export default class extends Controller {
      static targets = ["error", "form"]

      connect() {
        if (document.documentElement.hasAttribute("data-turbo-preview")) return

        this.markRead()
      }

      complete(event) {
        if (event.detail.success) return

        this.errorTarget.classList.remove("hidden")
      }

      failed(event) {
        event.preventDefault()
        event.stopPropagation()
        this.errorTarget.classList.remove("hidden")
      }

      retry() {
        this.errorTarget.classList.add("hidden")
        this.markRead()
      }

      markRead() {
        this.formTarget.requestSubmit()
      }
    }
  JAVASCRIPT

  create_file "app/javascript/controllers/notification_recipients_controller.js", <<~JAVASCRIPT, force: true
    import { Controller } from "@hotwired/stimulus"

    export default class extends Controller {
      static targets = ["audience", "count", "empty", "frame", "hidden", "search", "selector"]
      static values = { removeLabel: String, selected: Object, url: String }

      connect() {
        this.renderHiddenInputs()
        this.toggle()
      }

      toggle() {
        const selectedUsers = this.audienceTarget.value === "selected_users"
        this.selectorTarget.hidden = !selectedUsers
        this.searchTarget.disabled = !selectedUsers
        this.hiddenTarget.querySelectorAll("input").forEach((input) => { input.disabled = !selectedUsers })
      }

      search() {
        clearTimeout(this.timeout)
        this.timeout = setTimeout(() => this.loadResults(), 200)
      }

      select(event) {
        const { userId, userLabel } = event.currentTarget.dataset
        const selected = { ...this.selectedValue }
        selected[userId] = userLabel
        this.selectedValue = selected
        this.renderHiddenInputs()
        this.loadResults()
      }

      remove(event) {
        const selected = { ...this.selectedValue }
        delete selected[event.currentTarget.dataset.userId]
        this.selectedValue = selected
        this.renderHiddenInputs()
        if (this.searchTarget.value) this.loadResults()
      }

      loadResults() {
        const url = new URL(this.urlValue, window.location.origin)
        url.searchParams.set("q", this.searchTarget.value)
        Object.keys(this.selectedValue).forEach((id) => url.searchParams.append("selected_ids[]", id))
        this.frameTarget.src = url.toString()
      }

      renderHiddenInputs() {
        const entries = Object.entries(this.selectedValue)
        this.countTarget.textContent = entries.length
        this.emptyTarget.hidden = entries.length > 0
        this.hiddenTarget.hidden = entries.length === 0
        this.hiddenTarget.replaceChildren(...entries.map(([id, label]) => {
          const row = document.createElement("li")
          row.className = "list-row items-center"
          const input = document.createElement("input")
          input.type = "hidden"
          input.name = "notification[recipient_ids][]"
          input.value = id
          input.disabled = this.audienceTarget.value !== "selected_users"
          const name = document.createElement("span")
          name.className = "list-col-grow min-w-0 break-words"
          name.textContent = label
          const button = document.createElement("button")
          button.type = "button"
          button.className = "btn btn-outline btn-sm"
          button.textContent = this.removeLabelValue
          button.dataset.userId = id
          button.dataset.action = "notification-recipients#remove"
          row.append(name, button, input)
          return row
        }))
      }
    }
  JAVASCRIPT

