        find('button[popovertarget="notifications-popover"]').click
        find('button[popovertarget="notifications-popover"]').click
        assert_selector "#notifications-popover:popover-open a.tab-active",
          text: /\#{Regexp.escape(I18n.t('notifications.tabs.personal'))}/
        assert_operator resource_names.count { |name| name.match?(%r{/notifications/popover}) }, :>, popover_requests
      end

      test "keeps unread state on a failed announcement update and retries in place" do
        notification_deliveries(:one_published).open!
        @user.update!(global_notifications_read_at: 2.days.ago)
        original_cursor = @user.global_notifications_read_at
        cdp = page.driver.with_playwright_page do |playwright_page|
          playwright_page.context.new_cdp_session(playwright_page)
        end
        cdp.send_message("Network.enable")
        cdp.send_message("Network.setBlockedURLs", params: { urls: ["*notifications/global-read*"] })

        visit account_path
        find('button[popovertarget="notifications-popover"]').click
        within("#notifications-popover") { click_link I18n.t("notifications.tabs.announcements") }

        assert_selector "#popover_announcement_read_error.alert.alert-error.alert-soft",
          text: I18n.t("notifications.announcement_read_failed")
        assert_equal original_cursor, @user.reload.global_notifications_read_at
        assert_selector "#notification_unread_status .status"
        assert_selector "#popover_announcements_unread_status .status"

        cdp.send_message("Network.setBlockedURLs", params: { urls: [] })
        within("#popover_announcement_read_error") { click_button I18n.t("notifications.retry") }
        assert_no_selector "#popover_announcement_read_error", visible: :visible
        assert_no_selector "#notification_unread_status .status"
        assert_no_selector "#popover_announcements_unread_status .status"
      ensure
        cdp&.send_message("Network.setBlockedURLs", params: { urls: [] })
        cdp&.detach
      end

      test "advances notification history pagination and searches recipients in its frame" do
        30.times do |index|
          notification = Notification.new(message: "History \#{index}", published_at: index.minutes.ago,
            draft: false, audience: :selected_users)
          notification.save_with_delivery_synchronization!(recipient_ids: [@user.id])
        end
        visit notifications_path
        within("turbo-frame#notifications_history") do
          find("a[aria-label='\#{I18n.t('common.next')}']").click
        end
        assert_current_path notifications_path(page: 2), ignore_query: false

        30.times do |index|
          Notification.create!(message: "Announcement history \#{index}", published_at: index.minutes.ago,
            draft: false, audience: :all_users)
        end
        visit notifications_path(tab: "announcements")
        within("turbo-frame#notifications_history") do
          find("a[aria-label='\#{I18n.t('common.next')}']").click
        end
        assert_current_path %r{^/notifications[?](?:page=2&tab=announcements|tab=announcements&page=2)$},
          ignore_query: false

        @user.grant_role!(:admin)
        visit new_admin_notification_path
        assert_selector "lexxy-editor"
        assert_selector '[data-notification-recipients-target="selector"][hidden]', visible: :all
        select I18n.t("notifications.audiences.selected_users"), from: I18n.t("notifications.admin.audience")
        assert_no_selector '[data-notification-recipients-target="selector"][hidden]', visible: :all
        assert_selector '[data-notification-recipients-target="count"]', text: "0"
        assert_text I18n.t("notifications.admin.no_selected_recipients")
        display_name = T.must(@user.profile).display_name
        fill_in I18n.t("notifications.admin.recipient_search"), with: display_name
        assert_text display_name
        assert_selector "turbo-frame#notification_recipient_results button[data-user-id='\#{@user.id}']"
        within("turbo-frame#notification_recipient_results") do
          click_button I18n.t("notifications.admin.add_recipient")
        end
        assert_selector '[data-notification-recipients-target="count"]', text: "1"
        assert_no_text I18n.t("notifications.admin.no_selected_recipients")
        assert_no_selector "turbo-frame#notification_recipient_results button[data-user-id='\#{@user.id}']"
        within('[data-notification-recipients-target="hidden"]') do
          assert_selector "li.list-row", text: display_name
          click_button I18n.t("notifications.admin.remove_recipient")
        end
        assert_selector '[data-notification-recipients-target="count"]', text: "0"
        assert_text I18n.t("notifications.admin.no_selected_recipients")
        assert_selector "turbo-frame#notification_recipient_results button[data-user-id='\#{@user.id}']"
        assert_no_selector "input[name='notification[recipient_ids][]'][value='\#{@user.id}']"
      end

      test "edits a selected notification without losing existing recipients" do
        @user.grant_role!(:admin)
        notification = notifications(:published_selected)
        delivery = notification_deliveries(:one_published)
        delivery.open!
        expected_recipient_ids = notification.notification_deliveries.order(:user_id).pluck(:user_id)

        visit edit_admin_notification_path(notification)
        assert_selector "lexxy-editor"
        assert_selector '[data-notification-recipients-target="count"]', text: expected_recipient_ids.size.to_s
        expected_recipient_ids.each do |user_id|
          display_name = T.must(User.find(user_id).profile).display_name
          assert_selector '[data-notification-recipients-target="hidden"] li.list-row', text: display_name
          assert_selector "input[name='notification[recipient_ids][]'][value='\#{user_id}']", visible: :all
        end

        find("input[type='submit']").click

        assert_current_path admin_notification_path(notification)
        assert_equal expected_recipient_ids, notification.notification_deliveries.reload.order(:user_id).pluck(:user_id)
        assert_equal delivery.opened_at, delivery.reload.opened_at
      end

      private
        def resource_names
          page.evaluate_script("performance.getEntriesByType('resource').map((entry) => entry.name)")
        end
    end
  RUBY
end

def configure_default_views
  siwe_enabled = VALUES.fetch("additional_login_methods").include?("siwe")
  pwa_enabled = VALUES.fetch("pwa") == "use"
  web_push_enabled = VALUES.fetch("web_push") == "use"
  job_operations_enabled = VALUES.fetch("job_operations") == "enable"
  solid_queue_enabled = VALUES.fetch("active_job") == "solid_queue"
  maintenance_tasks_enabled = VALUES.fetch("maintenance_tasks") == "enable"
  api_enabled = VALUES.fetch("api") == "enable"
  profile_enabled = true
  avatar_enabled = true
  screen_name_enabled = true
  display_name_enabled = true
  account_navigation_count = 3 + (profile_enabled ? 1 : 0) + (api_enabled ? 1 : 0) +
    (web_push_enabled ? 1 : 0)
  account_page_description = if profile_enabled
    '<%= t("accounts.show.description_with_profile") %>'
  else
    '<%= t("accounts.show.description") %>'
  end
  account_page_action = if profile_enabled
    '<%= t("accounts.show.action_with_profile") %>'
  else
    '<%= t("accounts.show.action") %>'
  end
  home_action = '<%= link_to t("home.start_devise"), new_user_registration_path, class: action_button_classes(:primary) %>'
