    require "test_helper"

    class PushSubscriptionsControllerTest < ActionDispatch::IntegrationTest
    #{controller_test_support}
      teardown do
        @original_vapid.each { |name, value| value.nil? ? ENV.delete(name) : ENV[name] = value }
