  create_file "app/views/mission_control/jobs/jobs/index.html.erb", <<~'ERB', force: true
    <% jobs_title = job_operation_jobs_title(jobs_status) %>
    <% navigation(title: jobs_title, section: "#{jobs_status}_jobs".to_sym) %>
