        def prepare_authenticated_data
          profile = T.must(@user.profile)
          profile.update!(screen_name: "evidence_user", display_name: "Evidence User")
          profile.avatar.purge if profile.avatar.attached?
          @user.grant_role!(:admin)
          if @backup_admin.nil?
            @backup_admin = create_evidence_user("evidence-backup-admin")
            @backup_admin.grant_role!(:admin)
          end
          if MAINTENANCE_TASKS
            MaintenanceTasks::Run.delete_all
            clear_enqueued_jobs
            clear_performed_jobs
          end
          prepare_job_operations_data if JOB_OPERATIONS
          @regular_user = create_evidence_user("evidence-regular") if @regular_user.nil?
          prepare_notification_data
        end

        def prepare_notification_data
          3.times do |index|
            message = "Evidence notification #{index + 1}"
            rich_text = ActionText::RichText.find_by(
              record_type: "Notification",
              name: "message",
              body: message
            )
            notification = rich_text ? Notification.find(rich_text.record_id) : Notification.new(message:)
            notification.assign_attributes(
              published_at: (index + 1).minutes.ago,
              draft: false,
              audience: :selected_users
            )
            notification.save_with_delivery_synchronization!(recipient_ids: [@user.id])
            @evidence_notification = notification if index.zero?
          end
          3.times do |index|
            message = "Evidence announcement #{index + 1}"
            rich_text = ActionText::RichText.find_by(
              record_type: "Notification",
              name: "message",
              body: message
            )
            announcement = rich_text ? Notification.find(rich_text.record_id) : Notification.new(message:)
            announcement.assign_attributes(
              published_at: (index + 1).minutes.ago,
              draft: false,
              audience: :all_users
            )
            announcement.save_with_delivery_synchronization!
            raise "全体通知に個別配信行が作成されました" if announcement.notification_deliveries.exists?
            @evidence_announcement = announcement if index.zero?
          end
          @user.notification_deliveries.find_each do |delivery|
            delivery.update!(opened_at: nil)
          end
          @user.update!(global_notifications_read_at: 10.minutes.ago)
        end

        def prepare_job_operations_data
          return unless @evidence_failed_job.nil?

          active_job = EvidenceFailedJob.perform_later
          @evidence_failed_job = SolidQueue::Job.find_by!(active_job_id: active_job.job_id)
          T.must(@evidence_failed_job.ready_execution).destroy!
          @evidence_failed_job.failed_with(RuntimeError.new("Evidence failure"))
        end

