  create_file "test/annotations_test.rb", <<~RUBY, force: true
    # frozen_string_literal: true

    require "test_helper"
    require "open3"

    class AnnotationsTest < ActiveSupport::TestCase
      test "schema annotations are up to date" do
        stdout, stderr, status = Open3.capture3(
          { "RAILS_ENV" => "test" },
