def configure_database
  production_paths = {
    "primary" => "/rails/storage/production.sqlite3",
    "storage" => "/rails/storage/production_storage.sqlite3",
    "queue" => "/rails/storage/production_queue.sqlite3",
    "cache" => "/rails/storage/production_cache.sqlite3",
    "cable" => "/rails/storage/production_cable.sqlite3"
  }
  databases = {
    "primary" => { "database" => production_paths.fetch("primary") },
    "storage" => { "database" => production_paths.fetch("storage"), "migrations_paths" => "db/storage_migrate" }
  }
  if VALUES.fetch("active_job") == "solid_queue"
    databases["queue"] = { "database" => production_paths.fetch("queue"), "migrations_paths" => "db/queue_migrate" }
  end
  if VALUES.fetch("solid_cache") == "use"
    databases["cache"] = { "database" => production_paths.fetch("cache"), "migrations_paths" => "db/cache_migrate" }
  end
  if VALUES.fetch("action_cable") == "solid_cable"
    databases["cable"] = { "database" => production_paths.fetch("cable"), "migrations_paths" => "db/cable_migrate" }
  end
  production = databases.transform_values do |database|
    { "adapter" => "sqlite3", "pool" => "<%= ENV.fetch(\"DATABASE_POOL_SIZE\", ENV.fetch(\"RAILS_MAX_THREADS\", 5)) %>", "timeout" => 20_000, "transaction_mode" => "immediate" }.merge(database)
  end
  test_databases = {
    "primary" => { "database" => "storage/test.sqlite3" },
    "storage" => { "database" => "storage/test_storage.sqlite3", "migrations_paths" => "db/storage_migrate" }
  }
  if VALUES.fetch("job_operations") == "enable"
    test_databases["queue"] = { "database" => "storage/test_queue.sqlite3", "migrations_paths" => "db/queue_migrate" }
  end
  development_databases = {
    "primary" => { "database" => "storage/development.sqlite3" },
    "storage" => { "database" => "storage/development_storage.sqlite3", "migrations_paths" => "db/storage_migrate" }
  }
  if VALUES.fetch("active_job") == "solid_queue"
    development_databases["queue"] = {
      "database" => "storage/development_queue.sqlite3",
      "migrations_paths" => "db/queue_migrate"
    }
  end
  config = {
    "default" => { "adapter" => "sqlite3", "pool" => "<%= ENV.fetch(\"RAILS_MAX_THREADS\", 5) %>", "timeout" => 5000 },
    "development" => development_databases,
    "test" => test_databases,
    "production" => production
  }
  database_yaml = YAML.dump(config, line_width: -1)
    .sub("default:\n", "default: &default\n")
    .gsub(/^  ([a-z]+):\n(?=    (?:adapter|database):)/, "  \\1:\n    <<: *default\n")
  create_file "config/database.yml", database_yaml, force: true
end

def kamal_restore_cli_body
  <<~'RUBY'
    require "optparse"
    require "securerandom"
    require "shellwords"
    require "time"
    require_relative "../lib/deployment/kamal_operation" unless defined?(Deployment::KamalOperation)

    module KamalRestore
      Error = Deployment::KamalOperation::Error unless const_defined?(:Error, false)
      CommandRunner = Deployment::KamalOperation::CommandRunner

      class CLI
        def initialize(argv, input: $stdin, output: $stdout, error: $stderr, runner: nil)
          @argv = argv.dup
          @input = input
          @output = output
          @error = error
          @runner = runner || CommandRunner.new(output:, error:)
          @marker_created = false
          @quiesced = false
          @lock_held = false
          @database_swapped = false
        end

        def run
          options = parse_options
          @destination = options.fetch(:destination)
          @marker = ".kamal/#{APP_ID}-#{@destination}-restore-in-progress"
          @remote_state = Deployment::KamalOperation::RemoteState.new(destination: @destination, runner: @runner)
          if options.fetch(:rollback)
            run_rollback(options.fetch(:rollback))
          else
            run_restore(timestamp: options.fetch(:timestamp), plan_only: options.fetch(:plan))
          end
          0
        rescue OptionParser::ParseError, ArgumentError, Error => error
          @error.puts "Restore failed: #{error.message}"
          1
        rescue Interrupt
          @error.puts "Restore interrupted"
          130
        end

        private

        def parse_options
          options = { destination: nil, timestamp: nil, plan: false, rollback: nil }
          parser = OptionParser.new do |option_parser|
            option_parser.banner = "Usage: bin/kamal-restore --destination=production|staging [--plan] [--timestamp=RFC3339] | --rollback=OPERATION_ID"
            option_parser.on("--destination=DESTINATION") do |value|
              options[:destination] = value if %w[production staging].include?(value)
              raise OptionParser::InvalidArgument, "--destination must be production or staging" unless options[:destination]
            end
            option_parser.on("--timestamp=RFC3339") { |value| options[:timestamp] = normalize_timestamp(value) }
            option_parser.on("--plan") { options[:plan] = true }
            option_parser.on("--rollback=OPERATION_ID") { |value| options[:rollback] = validate_operation_id(value) }
          end
          parser.parse!(@argv)
          raise OptionParser::InvalidArgument, @argv.join(" ") unless @argv.empty?
          raise OptionParser::MissingArgument, "--destination" unless options.fetch(:destination)
          if options.fetch(:rollback) && (options.fetch(:timestamp) || options.fetch(:plan))
            raise OptionParser::InvalidArgument, "--rollback cannot be combined with --timestamp or --plan"
          end

          options
        end

        def normalize_timestamp(value)
          Time.iso8601(value).utc.iso8601
        rescue ArgumentError
          raise OptionParser::InvalidArgument, "--timestamp must be RFC3339"
        end

        def validate_operation_id(value)
          raise OptionParser::InvalidArgument, "invalid operation id" unless OPERATION_ID.match?(value)

          value
        end

        def run_restore(timestamp:, plan_only:)
          target = timestamp || "latest"
          @output.puts "Application: #{APP_ID}"
          @output.puts "Destination: #{@destination}"
          @output.puts "Restore target: #{target}"
          preview_restore(timestamp)
          return if plan_only

          confirm!("RESTORE #{APP_ID} #{@destination} #{target}")
          operation_id = "#{Time.now.utc.strftime(TIMESTAMP_FORMAT)}-#{SecureRandom.hex(6)}"
          begin
            begin_restore_operation(operation_id)
            quiesce_application
            sync_databases
            run_kamal!("accessory", "stop", "litestream")
            acquire_lock!("Restore #{APP_ID} #{operation_id}")
            app_exec!("bin/kamal-restore-volume", "prepare", operation_id)
            restore_databases(operation_id, timestamp)
            @database_swapped = true
            app_exec!("bin/kamal-restore-volume", "install", operation_id)
            release_lock!
            start_application
            remove_marker
          rescue StandardError, Interrupt
            recover_after_failure(operation_id:)
            raise
          end

          @output.puts "Restore completed: #{operation_id}"
          @output.puts "Rollback: mise exec -- bin/kamal-restore --destination=#{@destination} --rollback=#{operation_id}"
        end

        def run_rollback(operation_id)
          @output.puts "Application: #{APP_ID}"
          @output.puts "Destination: #{@destination}"
          @output.puts "Rollback operation: #{operation_id}"
          confirm!("ROLLBACK #{APP_ID} #{@destination} #{operation_id}")
          begin
            begin_restore_operation(operation_id)
            quiesce_application
            sync_databases
            run_kamal!("accessory", "stop", "litestream")
            acquire_lock!("Rollback #{APP_ID} #{operation_id}")
            @database_swapped = true
            app_exec!("bin/kamal-restore-volume", "rollback", operation_id)
            release_lock!
            start_application
            remove_marker
          rescue StandardError, Interrupt
            recover_after_failure(operation_id:)
            raise
          end

          @output.puts "Rollback completed: #{operation_id}"
        end

        def confirm!(phrase)
          unless @input.tty? && @output.tty?
            raise Error, "write operations require an interactive terminal"
          end

          @output.puts "Type the following phrase exactly to continue:"
          @output.puts phrase
          @output.print "> "
          @output.flush
          actual = @input.gets&.chomp
          raise Error, "confirmation did not match" unless actual == phrase
        end

        def preview_restore(timestamp)
          DATABASES.each do |database|
            @output.puts "\nDatabase: #{database.fetch("name")}"
            run_kamal!(*accessory_restore_command(
              database,
              output_path: "/tmp/#{APP_ID}-#{database.fetch("name")}-restore-preview.sqlite3",
              timestamp:,
              dry_run: true
            ))
          end
        end

        def begin_restore_operation(operation_id)
          acquire_lock!("Restore barrier #{APP_ID} #{operation_id}")
          raise Error, "maintenance mode is active for #{@destination}" if @remote_state.maintenance

          @remote_state.create_restore_marker
          @marker_created = true
          release_lock!
        rescue StandardError
          release_lock! if @lock_held
          remove_marker
          raise
        end

        def quiesce_application
          run_kamal!("app", "maintenance")
          @quiesced = true
          run_kamal!("app", "stop")
        end

        def sync_databases
          DATABASES.each do |database|
            run_kamal!(
              "accessory", "exec", "litestream", "--reuse",
              "litestream", "sync", "-socket", SOCKET_PATH, "-wait", "-timeout", "120",
              database.fetch("path")
            )
          end
        end

        def restore_databases(operation_id, timestamp)
          DATABASES.each do |database|
            output_path = "/rails/storage/.restore/#{operation_id}/staged/#{database.fetch("name")}.sqlite3"
            run_kamal!(*accessory_restore_command(database, output_path:, timestamp:, dry_run: true))
            run_kamal!(*accessory_restore_command(database, output_path:, timestamp:, dry_run: false))
          end
        end

        def accessory_restore_command(database, output_path:, timestamp:, dry_run:)
          command = [
            "accessory", "exec", "litestream",
            "restore", "-config", "/etc/litestream.yml", "-json", "-o", output_path
          ]
          command << "-dry-run" if dry_run
          command.concat(["-integrity-check", "full"]) unless dry_run
          command.concat(["-timestamp", timestamp]) if timestamp
          command << database.fetch("path")
          command
        end

        def app_exec!(*command)
          run_kamal!("app", "exec", "-p", "-r", "web", *command)
        end

        def server_exec!(*command)
          run_kamal!("server", "exec", Shellwords.join(command))
        end

        def acquire_lock!(message)
          @remote_state.acquire_lock(message)
          @lock_held = true
        end

        def release_lock!
          return unless @lock_held

          @remote_state.release_lock
          @lock_held = false
        end

        def start_application
          run_kamal!("accessory", "start", "litestream")
          app_exec!("bin/wait-for-litestream")
          run_kamal!("app", "start", "-r", "web")
          run_kamal!("app", "start", "-r", "worker") if HAS_WORKER
          run_kamal!("app", "live")
          @quiesced = false
        end

        def remove_marker
          return unless @marker_created

          @remote_state.delete_restore_marker
          @marker_created = false
        end

        def recover_after_failure(operation_id: nil)
          if @lock_held
            ignore_kamal_failure("lock", "release")
            @lock_held = false
          end

          if @database_swapped
            ignore_kamal_failure("app", "maintenance")
            ignore_kamal_failure("app", "stop")
            ignore_kamal_failure("accessory", "stop", "litestream")
            @error.puts "Database files changed; services remain stopped for inspection."
            @error.puts "Rollback: mise exec -- bin/kamal-restore --destination=#{@destination} --rollback=#{operation_id}" if operation_id
            return
          end

          if @quiesced
            ignore_kamal_failure("accessory", "start", "litestream")
            ignore_kamal_failure("app", "exec", "-p", "-r", "web", "bin/wait-for-litestream")
            ignore_kamal_failure("app", "start", "-r", "web")
            ignore_kamal_failure("app", "start", "-r", "worker") if HAS_WORKER
            ignore_kamal_failure("app", "live")
            @quiesced = false
          end
          if @marker_created
            ignore_kamal_failure("server", "exec", Shellwords.join(["rm", "-f", @marker]))
            @marker_created = false
          end
        end

        def run_kamal!(*arguments)
          @runner.run!(*arguments, "-d", @destination)
        end

        def ignore_kamal_failure(*arguments)
          @runner.ignore_failure(*arguments, "-d", @destination)
        end
      end
    end

    exit KamalRestore::CLI.new(ARGV).run if $PROGRAM_NAME == __FILE__
  RUBY
end

def configure_kamal_operation_support(app_id)
  support = <<~RUBY
    # frozen_string_literal: true

    require "base64"
    require "json"
    require "open3"
    require "shellwords"
    require "sorbet-runtime"

    module Deployment
      module KamalOperation
        APP_ID = #{app_id.inspect}
        DESTINATIONS = %w[production staging].freeze
  RUBY
  support << <<~'RUBY'

        class Error < StandardError; end

        class CommandRunner
          KAMAL = File.expand_path("../../bin/kamal", __dir__)

          def initialize(output: $stdout, error: $stderr, kamal: KAMAL)
            @output = output
            @error = error
            @kamal = kamal
          end

          def run!(*arguments)
            stdout, stderr, status = T.unsafe(Open3).capture3(@kamal, *arguments)
            @output.write(stdout)
            @error.write(stderr)
            return stdout if status.success?

            raise Error, "command failed (#{status.exitstatus}): bin/kamal #{arguments.join(" ")}"
          rescue SystemCallError => error
            raise Error, "could not execute bin/kamal: #{error.message}"
          end

          def ignore_failure(*arguments)
            T.unsafe(self).run!(*arguments)
          rescue Error => error
            @error.puts "cleanup warning: #{error.message}"
            nil
          end
        end

        class RemoteState
          attr_reader :maintenance_path, :restore_path

          def initialize(destination:, runner:)
            raise Error, "invalid destination: #{destination}" unless DESTINATIONS.include?(destination)

            @destination = destination
            @runner = runner
            @maintenance_path = ".kamal/#{APP_ID}-#{destination}-maintenance.json"
            @restore_path = ".kamal/#{APP_ID}-#{destination}-restore-in-progress"
          end

          def maintenance
            contents = server_exec!("if [ -f #{Shellwords.escape(maintenance_path)} ]; then cat #{Shellwords.escape(maintenance_path)}; fi")
            return nil if contents.strip.empty?

            JSON.parse(contents)
          rescue JSON::ParserError => error
            raise Error, "invalid maintenance state: #{error.message}"
          end

          def write_maintenance(state)
            encoded = Base64.strict_encode64(JSON.pretty_generate(state) + "\n")
            temporary_path = "#{maintenance_path}.tmp"
            server_exec!(
              "mkdir -p .kamal && printf %s #{Shellwords.escape(encoded)} | base64 -d > " \
                "#{Shellwords.escape(temporary_path)} && mv #{Shellwords.escape(temporary_path)} " \
                "#{Shellwords.escape(maintenance_path)}"
            )
          end

          def delete_maintenance
            server_exec!(Shellwords.join(["rm", "-f", maintenance_path]))
          end

          def restore_active?
            server_exec!(
              "if [ -e #{Shellwords.escape(restore_path)} ]; then printf true; else printf false; fi"
            ).strip == "true"
          end

          def create_restore_marker
            server_exec!(Shellwords.join(["mkdir", "-p", ".kamal"]))
            server_exec!(Shellwords.join(["touch", restore_path]))
          end

          def delete_restore_marker
            server_exec!(Shellwords.join(["rm", "-f", restore_path]))
          end

          def acquire_lock(message)
            kamal!("lock", "acquire", "-m", message)
          end

          def release_lock
            kamal!("lock", "release")
          end

          private

          def server_exec!(command)
            kamal!("server", "exec", command)
          end

          def kamal!(*arguments)
            @runner.run!(*arguments, "-d", @destination)
          end
        end
      end
    end
  RUBY
  create_file "lib/deployment/kamal_operation.rb", support, force: true
end

def configure_kamal_restore(app_id, databases)
  configure_kamal_operation_support(app_id)

  database_paths = databases.to_h { |database| [database.fetch("name"), database.fetch("path")] }
  volume_helper = <<~RUBY
    #!/usr/bin/env ruby
    APP_ID = #{app_id.inspect}
    DATABASE_PATHS = #{database_paths.inspect}.freeze
  RUBY
  volume_helper << <<~'RUBY'
    require "fileutils"
    require "json"

    STORAGE_ROOT = File.dirname(DATABASE_PATHS.values.fetch(0))
    RESTORE_ROOT = File.join(STORAGE_ROOT, ".restore")
    SIDECAR_SUFFIXES = ["", "-wal", "-shm", "-journal"].freeze
    OPERATION_ID = /\A\d{8}T\d{6}Z-[0-9a-f]{12}\z/

    def operation_directory(operation_id)
      raise "invalid operation id: #{operation_id}" unless OPERATION_ID.match?(operation_id)

      File.join(RESTORE_ROOT, operation_id)
    end

    def database_files(path)
      SIDECAR_SUFFIXES.map { |suffix| "#{path}#{suffix}" }
    end

    def fsync_directory(path)
      File.open(path) { |directory| directory.fsync }
    end

    def rename_file(source, destination)
      File.rename(source, destination)
      fsync_directory(File.dirname(source))
      fsync_directory(File.dirname(destination)) unless File.dirname(source) == File.dirname(destination)
    end

    def prepare(operation_id)
      directory = operation_directory(operation_id)
      raise "restore operation already exists: #{operation_id}" if File.exist?(directory)

      FileUtils.mkdir_p(File.join(directory, "staged"))
      fsync_directory(RESTORE_ROOT)
      puts directory
    end

    def install(operation_id)
      directory = operation_directory(operation_id)
      staged_directory = File.join(directory, "staged")
      previous_directory = File.join(directory, "previous")
      raise "restore operation is not prepared: #{operation_id}" unless File.directory?(staged_directory)
      raise "restore operation is already installed: #{operation_id}" if File.exist?(previous_directory)

      DATABASE_PATHS.each do |name, path|
        raise "staged database is missing: #{name}" unless File.file?(File.join(staged_directory, "#{name}.sqlite3"))
        raise "current database is missing: #{path}" unless File.file?(path)
      end

      FileUtils.mkdir(previous_directory)
      moved_previous = []
      installed = []
      begin
        DATABASE_PATHS.each_value do |path|
          database_files(path).select { |candidate| File.exist?(candidate) }.each do |source|
            destination = File.join(previous_directory, File.basename(source))
            rename_file(source, destination)
            moved_previous << [source, destination]
          end
        end
        DATABASE_PATHS.each do |name, path|
          source = File.join(staged_directory, "#{name}.sqlite3")
          rename_file(source, path)
          installed << [source, path]
        end

        manifest = {
          "schema_version" => 1,
          "app_id" => APP_ID,
          "operation_id" => operation_id,
          "database_paths" => DATABASE_PATHS,
          "installed_at" => Time.now.utc.iso8601
        }
        temporary_manifest = File.join(directory, "manifest.json.tmp")
        File.write(temporary_manifest, JSON.pretty_generate(manifest) + "\n")
        File.open(temporary_manifest) { |file| file.fsync }
        rename_file(temporary_manifest, File.join(directory, "manifest.json"))
      rescue Exception
        installed.reverse_each do |source, destination|
          rename_file(destination, source) if File.exist?(destination)
        end
        moved_previous.reverse_each do |source, destination|
          rename_file(destination, source) if File.exist?(destination)
        end
        raise
      end

      puts operation_id
    end

    def rollback(operation_id)
      directory = operation_directory(operation_id)
      previous_directory = File.join(directory, "previous")
      current_directory = File.join(directory, "replaced-by-rollback")
      manifest_path = File.join(directory, "manifest.json")
      raise "restore manifest is missing: #{operation_id}" unless File.file?(manifest_path)
      raise "rollback was already completed: #{operation_id}" if File.exist?(current_directory)

      manifest = JSON.parse(File.read(manifest_path))
      raise "restore manifest app id mismatch" unless manifest.fetch("app_id") == APP_ID
      raise "restore manifest database set mismatch" unless manifest.fetch("database_paths") == DATABASE_PATHS
      DATABASE_PATHS.each_value do |path|
        previous = File.join(previous_directory, File.basename(path))
        raise "previous database is missing: #{previous}" unless File.file?(previous)
        raise "current database is missing: #{path}" unless File.file?(path)
      end

      FileUtils.mkdir(current_directory)
      moved_current = []
      restored_previous = []
      begin
        DATABASE_PATHS.each_value do |path|
          database_files(path).select { |candidate| File.exist?(candidate) }.each do |source|
            destination = File.join(current_directory, File.basename(source))
            rename_file(source, destination)
            moved_current << [source, destination]
          end
        end
        DATABASE_PATHS.each_value do |path|
          database_files(path).each do |destination|
            source = File.join(previous_directory, File.basename(destination))
            next unless File.exist?(source)

            rename_file(source, destination)
            restored_previous << [source, destination]
          end
        end
      rescue Exception
        restored_previous.reverse_each do |source, destination|
          rename_file(destination, source) if File.exist?(destination)
        end
        moved_current.reverse_each do |source, destination|
          rename_file(destination, source) if File.exist?(destination)
        end
        raise
      end

      puts operation_id
    end

    require "time"

    command, operation_id, *extra = ARGV
    raise "usage: bin/kamal-restore-volume prepare|install|rollback OPERATION_ID" if command.nil? || operation_id.nil? || extra.any?

    case command
    when "prepare" then prepare(operation_id)
    when "install" then install(operation_id)
    when "rollback" then rollback(operation_id)
    else raise "unknown command: #{command}"
    end
  RUBY
  create_file "bin/kamal-restore-volume", volume_helper, force: true
  chmod "bin/kamal-restore-volume", 0o755

  restore_cli = <<~RUBY
    #!/usr/bin/env ruby
    module KamalRestore
      APP_ID = #{app_id.inspect}
      DATABASES = #{databases.inspect}.freeze
      HAS_WORKER = #{databases.any? { |database| database.fetch("name") == "queue" }}
  RUBY
  restore_cli << <<~'RUBY'
      SOCKET_PATH = "/rails/storage/.litestream.sock"
      TIMESTAMP_FORMAT = "%Y%m%dT%H%M%SZ"
      OPERATION_ID = /\A\d{8}T\d{6}Z-[0-9a-f]{12}\z/

    end
  RUBY
  restore_cli << kamal_restore_cli_body
  create_file "bin/kamal-restore", restore_cli, force: true
  chmod "bin/kamal-restore", 0o755
end

def configure_kamal_maintenance(app_id, databases)
  default_message = if VALUES.fetch("default_locale") == "ja"
    "ただいまメンテナンス中です。しばらくしてからもう一度お試しください。"
  else
    "We are currently performing maintenance. Please try again later."
  end
  default_message_literal = JSON.generate(
    default_message.dup.force_encoding(Encoding::UTF_8),
    ascii_only: true
  )
  maintenance_cli = <<~RUBY
    #!/usr/bin/env ruby
    module KamalMaintenance
      APP_ID = #{app_id.inspect}
      DATABASES = #{databases.inspect}.freeze
      HAS_WORKER = #{databases.any? { |database| database.fetch("name") == "queue" }}
      DEFAULT_MESSAGE = #{default_message_literal}
  RUBY
  maintenance_cli << <<~'RUBY'
      SOCKET_PATH = "/rails/storage/.litestream.sock"
      ACTIONS = %w[start status message finish].freeze
      MUTATING_ACTIONS = %w[start message finish].freeze
    end

    require "cgi"
    require "gum"
    require "json"
    require "net/http"
    require "optparse"
    require "time"
    require "uri"
    require "yaml"
    require_relative "../lib/deployment/kamal_operation" unless defined?(Deployment::KamalOperation)

    module KamalMaintenance
      Error = Deployment::KamalOperation::Error unless const_defined?(:Error, false)

      class Inspector
        def initialize(destination:, runner:)
          @destination = destination
          @runner = runner
        end

        def running_roles
          server_exec!(
            "docker ps --filter label=service=#{APP_ID} " \
              "--filter label=destination=#{@destination} --format '{{.Label \"role\"}}'"
          ).lines.map(&:strip).reject(&:empty?).uniq.sort
        end

        def litestream_running?
          server_exec!(
            "docker inspect -f '{{.State.Running}}' #{APP_ID}-litestream 2>/dev/null || printf false"
          ).strip == "true"
        end

        def public_response(path: nil)
          uri = URI.parse(application_origin)
          uri.path = path if path
          request = Net::HTTP::Get.new(uri)
          response = Net::HTTP.start(
            uri.host,
            uri.port,
            use_ssl: uri.scheme == "https",
            open_timeout: 10,
            read_timeout: 10
          ) { |http| http.request(request) }
          { "code" => response.code.to_i, "body" => response.body.to_s }
        rescue URI::InvalidURIError, SocketError, SystemCallError, Timeout::Error => error
          raise Error, "public health check failed: #{error.message}"
        end

        private

        def application_origin
          config = YAML.safe_load(kamal!("config"), aliases: false)
          origin = config.dig("env", "clear", "APPLICATION_ORIGIN")
          raise Error, "APPLICATION_ORIGIN is missing from Kamal configuration" if origin.to_s.empty?

          origin
        rescue Psych::Exception => error
          raise Error, "could not read Kamal configuration: #{error.message}"
        end

        def server_exec!(command)
          kamal!("server", "exec", command)
        end

        def kamal!(*arguments)
          @runner.run!(*arguments, "-d", @destination)
        end
      end

      class CLI
        def initialize(
          argv,
          input: $stdin,
          output: $stdout,
          error: $stderr,
          runner: nil,
          prompt: Gum,
          state_store: nil,
          inspector: nil,
          now: -> { Time.now.utc }
        )
          @argv = argv.dup
          @input = input
          @output = output
          @error = error
          @runner = runner || Deployment::KamalOperation::CommandRunner.new(output:, error:)
          @prompt = prompt
          @state_store = state_store
          @inspector = inspector
          @now = now
          @current_step = nil
          @operation_started = false
        end

        def run
          options = parse_options
          @action = options.fetch(:action)
          @destination = options.fetch(:destination)
          @state_store ||= Deployment::KamalOperation::RemoteState.new(destination: @destination, runner: @runner)
          @inspector ||= Inspector.new(destination: @destination, runner: @runner)

          case @action
          when "start" then start(options.fetch(:message))
          when "status" then status
          when "message" then update_message(options.fetch(:message))
          when "finish" then finish
          end
          0
        rescue OptionParser::ParseError, ArgumentError, Error => error
          @error.puts "Maintenance failed: #{error.message}"
          1
        rescue Interrupt
          record_failure("interrupted") if @state
          @error.puts "Maintenance interrupted"
          130
        end

        private

        def parse_options
          action = @argv.shift
          raise OptionParser::InvalidArgument, "action must be start, status, message, or finish" unless ACTIONS.include?(action)

          options = { action:, destination: nil, message: nil }
          parser = OptionParser.new do |option_parser|
            option_parser.banner = "Usage: bin/kamal-maintenance start|status|message|finish --destination=production|staging [--message=TEXT]"
            option_parser.on("--destination=DESTINATION") do |value|
              unless Deployment::KamalOperation::DESTINATIONS.include?(value)
                raise OptionParser::InvalidArgument, "--destination must be production or staging"
              end
              options[:destination] = value
            end
            option_parser.on("--message=TEXT") { |value| options[:message] = validate_message(value) }
          end
          parser.parse!(@argv)
          raise OptionParser::InvalidArgument, @argv.join(" ") unless @argv.empty?
          raise OptionParser::MissingArgument, "--destination" unless options.fetch(:destination)
          if options.fetch(:message) && !%w[start message].include?(action)
            raise OptionParser::InvalidArgument, "--message is only valid with start or message"
          end

          options
        end

        def validate_message(value)
          message = String(value)
          raise OptionParser::InvalidArgument, "message must not be empty" if message.empty?
          raise OptionParser::InvalidArgument, "message must be one line of plain text" if message.match?(/[[:cntrl:]]/)
          raise OptionParser::InvalidArgument, "message must be at most 500 characters" if message.length > 500

          message
        end

        def requested_message(option, default: DEFAULT_MESSAGE)
          return option if option

          ensure_tty!
          value = @prompt.input(header: "Maintenance message", value: default)
          validate_message(value)
        end

        def confirm!(description)
          ensure_tty!

          accepted = @prompt.confirm(
            description,
            default: false,
            affirmative: "実行",
            negative: "中止"
          )
          raise Error, "cancelled" unless accepted
        end

        def ensure_tty!
          return if @input.tty? && @output.tty?

          raise Error, "write operations require an interactive terminal"
        end

        def start(message_option)
          @state = @state_store.maintenance
          message = requested_message(message_option, default: @state&.fetch("message", nil) || DEFAULT_MESSAGE)
          confirm!("#{APP_ID} (#{@destination}) をメンテナンスモードにしますか？")
          if @state
            unless %w[starting start_failed].include?(@state.fetch("phase"))
              raise Error, "maintenance state is #{@state.fetch("phase")}; use the matching subcommand"
            end
            message_changed = @state.fetch("message") != message
            @state["message"] = message
            @state["failed_step"] = nil
            @state["error"] = nil
          else
            @operation_started = true
            create_start_state(message)
          end
          @operation_started = true

          @step_sequence = [
            "state_created", "proxy_maintenance", "app_stopped", "app_stop_verified",
            *DATABASES.map { |database| "litestream_synced_#{database.fetch("name")}" },
            "litestream_stopped", "litestream_stop_verified", "public_maintenance_verified", "active"
          ]
          if message_changed && completed_step?("proxy_maintenance")
            @current_step = "proxy_maintenance"
            run_kamal!("app", "maintenance", "--message", message)
            write_state(message:)
          end
          prepare_start_resume!

          perform_step("proxy_maintenance") { run_kamal!("app", "maintenance", "--message", message) }
          perform_step("app_stopped") { run_kamal!("app", "stop") }
          perform_step("app_stop_verified") do
            roles = @inspector.running_roles
            raise Error, "application roles are still running: #{roles.join(", ")}" unless roles.empty?
          end
          DATABASES.each do |database|
            perform_step("litestream_synced_#{database.fetch("name")}") do
              run_kamal!(
                "accessory", "exec", "litestream", "--reuse",
                "litestream", "sync", "-socket", SOCKET_PATH, "-wait", "-timeout", "120",
                database.fetch("path")
              )
            end
          end
          perform_step("litestream_stopped") { run_kamal!("accessory", "stop", "litestream") }
          perform_step("litestream_stop_verified") do
            raise Error, "Litestream is still running" if @inspector.litestream_running?
          end
          perform_step("public_maintenance_verified") { verify_public_maintenance!(message) }
          write_state(phase: "active", last_successful_step: "active", failed_step: nil, error: nil)
          @output.puts "Maintenance mode is active for #{APP_ID} (#{@destination})."
        rescue StandardError => error
          fail_closed_after_start(message) if @operation_started && @state
          record_failure(error.message, phase: "start_failed") if @operation_started && @state
          raise
        end

        def update_message(message_option)
          @state = @state_store.maintenance
          raise Error, "maintenance mode is not active" unless @state
          raise Error, "maintenance phase must be active" unless @state.fetch("phase") == "active"
          message = requested_message(message_option, default: @state.fetch("message"))
          confirm!("#{APP_ID} (#{@destination}) のメンテナンス文言を変更しますか？")

          @operation_started = true
          @current_step = "message_updated"
          run_kamal!("app", "maintenance", "--message", message)
          verify_public_maintenance!(message)
          write_state(message:, last_successful_step: "message_updated", failed_step: nil, error: nil)
          @output.puts "Maintenance message updated."
        rescue StandardError => error
          record_failure(error.message, phase: "active") if @operation_started && @state
          raise
        end

        def finish
          confirm!("#{APP_ID} (#{@destination}) のメンテナンスモードを終了しますか？")
          @state = @state_store.maintenance
          raise Error, "maintenance mode is not active" unless @state
          unless %w[active finishing finish_failed].include?(@state.fetch("phase"))
            raise Error, "maintenance phase is #{@state.fetch("phase")}; finish cannot continue"
          end
          @operation_started = true
          write_state(phase: "finishing", failed_step: nil, error: nil)

          @step_sequence = [
            "active", "litestream_started", "litestream_ready", "web_started",
            *(HAS_WORKER ? ["worker_started"] : []),
            "app_roles_verified", "internal_health_verified", "proxy_live", "public_health_verified"
          ]
          @proxy_live = false

          perform_step("litestream_started") { run_kamal!("accessory", "start", "litestream") }
          perform_step("litestream_ready") { verify_litestream_ready! }
          perform_step("web_started") { run_kamal!("app", "start", "-r", "web") }
          perform_step("worker_started") { run_kamal!("app", "start", "-r", "worker") } if HAS_WORKER
          perform_step("app_roles_verified") { verify_running_roles! }
          perform_step("internal_health_verified") { app_exec!(*internal_health_command) }
          perform_step("proxy_live") do
            run_kamal!("app", "live")
            @proxy_live = true
          end
          perform_step("public_health_verified") { verify_public_health! }
          remove_state_under_lock
          @state = nil
          @output.puts "Maintenance mode finished for #{APP_ID} (#{@destination})."
        rescue StandardError => error
          fail_closed_after_finish(error) if @operation_started
          raise
        end

        def status
          @state = @state_store.maintenance
          roles = @inspector.running_roles
          litestream = @inspector.litestream_running?
          response = @inspector.public_response(path: @state ? nil : "/up")
          @output.puts "Application: #{APP_ID}"
          @output.puts "Destination: #{@destination}"
          @output.puts "Phase: #{@state&.fetch("phase", nil) || "inactive"}"
          @output.puts "Message: #{@state.fetch("message")}" if @state
          @output.puts "Started at: #{@state.fetch("started_at")}" if @state
          @output.puts "Last successful step: #{@state.fetch("last_successful_step")}" if @state
          @output.puts "Failed step: #{@state.fetch("failed_step")}" if @state&.fetch("failed_step", nil)
          @output.puts "Error: #{@state.fetch("error")}" if @state&.fetch("error", nil)
          @output.puts "Running roles: #{roles.empty? ? "none" : roles.join(", ")}"
          @output.puts "Litestream: #{litestream ? "running" : "stopped"}"
          @output.puts "Public HTTP status: #{response.fetch("code")}"
          verify_status_consistency!(@state, roles, litestream, response)
        end

        def create_start_state(message)
          @state_store.acquire_lock("Maintenance barrier #{APP_ID}")
          begin
            raise Error, "database restore is in progress" if @state_store.restore_active?
            raise Error, "maintenance state was created concurrently" if @state_store.maintenance

            timestamp = @now.call.iso8601
            @state = {
              "schema_version" => 1,
              "phase" => "starting",
              "destination" => @destination,
              "message" => message,
              "started_at" => timestamp,
              "updated_at" => timestamp,
              "last_successful_step" => "state_created",
              "failed_step" => nil,
              "error" => nil
            }
            @state_store.write_maintenance(@state)
          ensure
            @state_store.release_lock
          end
        end

        def perform_step(step)
          return if completed_step?(step)

          @current_step = step
          yield
          write_state(last_successful_step: step, failed_step: nil, error: nil)
        end

        def completed_step?(step)
          previous = @step_sequence.index(@state.fetch("last_successful_step"))
          current = @step_sequence.index(step)
          previous && current && previous >= current
        end

        def prepare_start_resume!
          return unless completed_step?("app_stop_verified")

          roles = @inspector.running_roles
          raise Error, "application roles restarted during maintenance: #{roles.join(", ")}" unless roles.empty?

          final_sync_step = "litestream_synced_#{DATABASES.last.fetch("name")}"
          needs_litestream = !completed_step?(final_sync_step)
          run_kamal!("accessory", "start", "litestream") if needs_litestream && !@inspector.litestream_running?
        end

        def write_state(**changes)
          @state.merge!(changes.transform_keys(&:to_s))
          @state["updated_at"] = @now.call.iso8601
          @state_store.write_maintenance(@state)
        end

        def record_failure(message, phase: nil)
          write_state(
            phase: phase || @state.fetch("phase"),
            failed_step: @current_step || "unknown",
            error: message
          )
        rescue StandardError => state_error
          @error.puts "Could not record maintenance failure: #{state_error.message}"
        end

        def fail_closed_after_finish(error)
          return unless @state

          if @proxy_live || %w[proxy_live public_health_verified].include?(@state.fetch("last_successful_step", nil))
            @runner.ignore_failure(
              "app", "maintenance", "--message", @state.fetch("message"), "-d", @destination
            )
            @state["last_successful_step"] = "internal_health_verified"
          end
          record_failure(error.message, phase: "finish_failed")
        end

        def fail_closed_after_start(message)
          @runner.ignore_failure("app", "maintenance", "--message", message, "-d", @destination)
          @runner.ignore_failure("app", "stop", "-d", @destination)
        end

        def remove_state_under_lock
          @state_store.acquire_lock("Maintenance completed #{APP_ID}")
          begin
            @state_store.delete_maintenance
          ensure
            @state_store.release_lock
          end
        end

        def verify_running_roles!
          roles = @inspector.running_roles
          required = HAS_WORKER ? %w[web worker] : %w[web]
          missing = required - roles
          raise Error, "application roles did not start: #{missing.join(", ")}" unless missing.empty?
        end

        def verify_litestream_ready!
          database = DATABASES.fetch(0)
          run_kamal!(
            "accessory", "exec", "litestream", "--reuse",
            "litestream", "sync", "-socket", SOCKET_PATH, "-wait", "-timeout", "60",
            database.fetch("path")
          )
        end

        def verify_public_maintenance!(message)
          response = @inspector.public_response
          raise Error, "public response was #{response.fetch("code")}, expected 503" unless response.fetch("code") == 503
          visible_body = CGI.unescapeHTML(response.fetch("body"))
          raise Error, "public maintenance message did not match" unless visible_body.include?(message)
        end

        def verify_public_health!
          response = @inspector.public_response(path: "/up")
          raise Error, "public /up response was #{response.fetch("code")}, expected 200" unless response.fetch("code") == 200
        end

        def verify_status_consistency!(state, roles, litestream, response)
          if state
            visible_body = CGI.unescapeHTML(response.fetch("body"))
            expected = roles.empty? && !litestream && response.fetch("code") == 503 &&
              visible_body.include?(state.fetch("message"))
            raise Error, "remote state and running services are inconsistent" unless expected
          else
            required = HAS_WORKER ? %w[web worker] : %w[web]
            expected = (required - roles).empty? && litestream && response.fetch("code") == 200
            raise Error, "inactive marker and running services are inconsistent" unless expected
          end
        end

        def internal_health_command
          [
            "ruby", "-rnet/http", "-e",
            "response = Net::HTTP.get_response(URI('http://127.0.0.1:80/up')); exit(response.code.to_i == 200 ? 0 : 1)"
          ]
        end

        def app_exec!(*command)
          run_kamal!("app", "exec", "-p", "-r", "web", *command)
        end

        def run_kamal!(*arguments)
          @runner.run!(*arguments, "-d", @destination)
        end
      end
    end

    exit KamalMaintenance::CLI.new(ARGV).run if $PROGRAM_NAME == __FILE__
  RUBY
  create_file "bin/kamal-maintenance", maintenance_cli, force: true
  chmod "bin/kamal-maintenance", 0o755
end

def configure_deployment(app_id)
  create_file "lib/deployment/command_runner.rb", <<~'RUBY', force: true
    # typed: strict
    # frozen_string_literal: true

    require "open3"
    require "sorbet-runtime"

    module Deployment
      Error = Class.new(StandardError)

      class Result < T::Struct
        const :stdout, String
        const :stderr, String
        const :success, T::Boolean
        const :exitstatus, Integer
      end

      class CommandRunner
        extend T::Sig

        sig do
          params(
            command: T::Array[String],
            environment: T::Hash[String, String],
            stdin_data: T.nilable(String)
          ).returns(Result)
        end
        def capture(command, environment: {}, stdin_data: nil)
          stdout, stderr, status = T.unsafe(Open3).capture3(environment, *command, stdin_data: stdin_data)
          Result.new(stdout:, stderr:, success: status.success?, exitstatus: status.exitstatus || 1)
        rescue Errno::ENOENT => error
          Result.new(stdout: "", stderr: error.message, success: false, exitstatus: 127)
        end

        sig { params(command: T::Array[String], environment: T::Hash[String, String]).returns(Integer) }
        def run(command, environment: {})
          T.unsafe(Kernel).system(environment, *command) == true ? 0 : 1
        end
      end
    end
  RUBY

  create_file "lib/deployment/cloudflare_client.rb", <<~'RUBY', force: true
    # typed: strict
    # frozen_string_literal: true

    require "json"
    require "net/http"
    require "pathname"
    require "sorbet-runtime"
    require "uri"
    require "deployment/command_runner"

    module Deployment
      class CloudflareClient
        extend T::Sig

        API_BASE_URL = "https://api.cloudflare.com/client/v4"

        class RequestError < Error
          extend T::Sig

          sig { returns(Integer) }
          attr_reader :status

          sig { returns(T::Array[Integer]) }
          attr_reader :codes

          sig { params(message: String, status: Integer, codes: T::Array[Integer]).void }
          def initialize(message, status:, codes:)
            super(message)
            @status = status
            @codes = codes
          end
        end

        sig do
          params(
            token: String,
            root: Pathname,
            runner: T.untyped,
            http_factory: T.untyped,
            api_client: T.untyped
          ).void
        end
        def initialize(token:, root: Pathname.pwd, runner: CommandRunner.new, http_factory: nil, api_client: nil)
          @token = token
          @runner = runner
          @wrangler = T.let(root.join("node_modules/.bin/wrangler").to_s, String)
          @api_client = api_client
          @http_factory = T.let(
            http_factory || ->(host, port) { Net::HTTP.new(host, port) },
            T.untyped
          )
        end

        sig { void }
        def validate_dependency!
          raise Error, "Wrangler v4が見つかりません。npm installを実行してください: #{@wrangler}" unless File.executable?(@wrangler)

          version = command!([@wrangler, "--version"])
          raise Error, "Wrangler v4が必要です: #{version.strip}" unless version.match?(/\b4\.\d+\.\d+\b/)
        end

        sig { returns(T::Hash[String, T.untyped]) }
        def identity
          value = json_command!([@wrangler, "whoami", "--json"])
          unless value.is_a?(Hash) && value["loggedIn"]
            raise Error, "WranglerはCloudflareへログインしていません"
          end
          accounts = value["accounts"]
          raise Error, "Wranglerのログイン先Cloudflare accountがありません" unless accounts.is_a?(Array) && accounts.any?

          value
        end

        sig { params(account_id: String, buckets: T::Array[String]).returns(T::Array[String]) }
        def existing_buckets(account_id, buckets)
          buckets.filter_map do |bucket|
            result = @runner.capture(
              [@wrangler, "r2", "bucket", "info", bucket, "--json"],
              environment: { "CLOUDFLARE_ACCOUNT_ID" => account_id },
              stdin_data: nil
            )
            unless result.success
              diagnostic = [result.stdout, result.stderr].join("\n")
              next if diagnostic.match?(/\[code: 10006\]/)

              detail = [result.stdout, result.stderr].map(&:strip).reject(&:empty?).join("\n")
              detail = "exit status #{result.exitstatus}" if detail.empty?
              raise Error, "R2 bucket確認に失敗しました (#{bucket}): #{detail}"
            end

            parsed = JSON.parse(result.stdout)
            raise Error, "Wranglerのbucket情報応答が不正です: #{bucket}" unless parsed.is_a?(Hash) && parsed["name"] == bucket

            bucket
          end
        rescue JSON::ParserError
          raise Error, "Wranglerのbucket情報JSON応答が不正です"
        end

        sig { params(account_id: String, bucket: String).void }
        def create_bucket(account_id, bucket)
          command!([@wrangler, "r2", "bucket", "create", bucket], environment: { "CLOUDFLARE_ACCOUNT_ID" => account_id })
        end

        sig { params(account_id: String).returns(T::Hash[String, T.untyped]) }
        def verify_token(account_id)
          return @api_client.verify_token(account_id) if @api_client

          result = request(:get, "/accounts/#{account_id}/tokens/verify")["result"]
          raise Error, "Cloudflare Initial Token検証応答が不正です" unless result.is_a?(Hash)

          result
        end

        sig { params(account_id: String, token_id: String).returns(T::Hash[String, T.untyped]) }
        def token_details(account_id, token_id)
          return @api_client.token_details(account_id, token_id) if @api_client

          result = request(:get, "/accounts/#{account_id}/tokens/#{token_id}")["result"]
          raise Error, "Cloudflare Initial Token詳細応答が不正です" unless result.is_a?(Hash)

          result
        end

        sig { params(account_id: String, name: String).returns(T::Array[T::Hash[String, T.untyped]]) }
        def permission_groups(account_id, name:)
          return @api_client.permission_groups(account_id, name:) if @api_client

          result = request(
            :get,
            "/accounts/#{account_id}/tokens/permission_groups",
            query: { "name" => name }
          )["result"]
          raise Error, "Cloudflare permission group一覧応答が不正です" unless result.is_a?(Array)

          typed_records(result, "Cloudflare permission group")
        end

        sig { params(account_id: String).returns(T::Array[T::Hash[String, T.untyped]]) }
        def tokens(account_id)
          return @api_client.tokens(account_id) if @api_client

          records = T.let([], T::Array[T::Hash[String, T.untyped]])
          page = 1
          loop do
            envelope = request(
              :get,
              "/accounts/#{account_id}/tokens",
              query: { "page" => page.to_s, "per_page" => "50" }
            )
            result = envelope["result"]
            result_info = envelope["result_info"]
            unless result.is_a?(Array) && result_info.is_a?(Hash)
              raise Error, "Cloudflare token一覧応答が不正です"
            end

            records.concat(typed_records(result, "Cloudflare token"))
            total_count = result_info["total_count"]
            raise Error, "Cloudflare token一覧の件数応答が不正です" unless total_count.is_a?(Integer) && total_count >= 0
            break if records.length >= total_count
            raise Error, "Cloudflare token一覧のpagination応答が不正です" if result.empty?

            page += 1
          end
          records
        end

        sig do
          params(
            account_id: String,
            name: String,
            policy: T::Hash[String, T.untyped]
          ).returns(T::Hash[String, T.untyped])
        end
        def create_token(account_id, name:, policy:)
          return @api_client.create_token(account_id, name:, policy:) if @api_client

          result = request(
            :post,
            "/accounts/#{account_id}/tokens",
            body: { "name" => name, "policies" => [policy] }
          )["result"]
          raise Error, "Cloudflare token作成応答が不正です" unless result.is_a?(Hash)

          result
        end

        private

        sig do
          params(
            command: T::Array[String],
            environment: T::Hash[String, String]
          ).returns(String)
        end
        def command!(command, environment: {})
          result = @runner.capture(command, environment:, stdin_data: nil)
          return result.stdout if result.success

          detail = [result.stdout, result.stderr].map(&:strip).reject(&:empty?).join("\n")
          detail = "exit status #{result.exitstatus}" if detail.empty?
          raise Error, "Wrangler commandに失敗しました: #{detail}"
        end

        sig { params(command: T::Array[String]).returns(T.untyped) }
        def json_command!(command)
          JSON.parse(command!(command))
        rescue JSON::ParserError
          raise Error, "WranglerのJSON応答が不正です"
        end

        sig do
          params(
            method: Symbol,
            path: String,
            query: T::Hash[String, String],
            body: T.nilable(T::Hash[String, T.untyped])
          ).returns(T::Hash[String, T.untyped])
        end
        def request(method, path, query: {}, body: nil)
          uri = URI("#{API_BASE_URL}#{path}")
          uri.query = URI.encode_www_form(query) unless query.empty?
          request = case method
          when :get
            Net::HTTP::Get.new(uri)
          when :post
            Net::HTTP::Post.new(uri)
          else
            raise Error, "未対応のCloudflare API methodです: #{method}"
          end
          request["Authorization"] = "Bearer #{@token}"
          request["Content-Type"] = "application/json"
          request.body = JSON.generate(body) if body

          http = @http_factory.call(T.must(uri.host), uri.port)
          http.use_ssl = true
          http.open_timeout = 10
          http.read_timeout = 30
          http.write_timeout = 30
          response = http.request(request)
          envelope = JSON.parse(response.body)
          raise Error, "Cloudflare APIのJSON応答が不正です" unless envelope.is_a?(Hash)
          return envelope if response.code.to_i.between?(200, 299) && envelope["success"] == true

          status = response.code.to_i
          detail = redact_secret(error_detail(envelope))
          raise RequestError.new(
            "Cloudflare API requestに失敗しました (HTTP #{response.code}): #{detail}",
            status:,
            codes: error_codes(envelope)
          )
        rescue Error
          raise
        rescue JSON::ParserError
          raise Error, "Cloudflare APIのJSON応答が不正です"
        rescue StandardError => error
          detail = redact_secret("#{error.class}: #{error.message}")
          raise Error, "Cloudflare API requestに失敗しました: #{detail}"
        end

        sig { params(records: T::Array[T.untyped], label: String).returns(T::Array[T::Hash[String, T.untyped]]) }
        def typed_records(records, label)
          records.map do |record|
            raise Error, "#{label}応答が不正です" unless record.is_a?(Hash)

            record
          end
        end

        sig { params(envelope: T::Hash[String, T.untyped]).returns(String) }
        def error_detail(envelope)
          errors = envelope["errors"]
          return "Cloudflareから詳細が返されませんでした" unless errors.is_a?(Array)

          messages = errors.filter_map do |error|
            next unless error.is_a?(Hash)

            code = error["code"]
            message = error["message"]
            next unless message.is_a?(String) && !message.empty?

            code.is_a?(Integer) ? "#{message} (code: #{code})" : message
          end
          messages.empty? ? "Cloudflareから詳細が返されませんでした" : messages.join("; ")
        end

        sig { params(envelope: T::Hash[String, T.untyped]).returns(T::Array[Integer]) }
        def error_codes(envelope)
          errors = envelope["errors"]
          return [] unless errors.is_a?(Array)

          errors.filter_map do |error|
            code = error["code"] if error.is_a?(Hash)
            code if code.is_a?(Integer)
          end
        end

        sig { params(value: String).returns(String) }
        def redact_secret(value)
          @token.empty? ? value : value.gsub(@token, "[REDACTED]")
        end
      end
    end
  RUBY

  create_file "lib/deployment/one_password_client.rb", <<~'RUBY', force: true
    # typed: strict
    # frozen_string_literal: true

    require "json"
    require "sorbet-runtime"
    require "deployment/command_runner"

    module Deployment
      class OnePasswordClient
        extend T::Sig

        sig { params(runner: T.untyped).void }
        def initialize(runner: CommandRunner.new)
          @runner = runner
        end

        sig { returns(String) }
        def version
          command!(%w[op --version])
        end

        sig { returns(T::Array[T::Hash[String, T.untyped]]) }
        def accounts
          records(json_command!(%w[op account list --format=json]), "1Password account")
        end

        sig { params(account_id: String).returns(T::Hash[String, T.untyped]) }
        def current_user(account_id)
          record(json_command!(%W[op user get --me --format=json --account #{account_id}]), "1Password identity")
        end

        sig { params(account_id: String).returns(T::Array[T::Hash[String, T.untyped]]) }
        def vaults(account_id)
          records(json_command!(%W[op vault list --format=json --account #{account_id}]), "1Password vault")
        end

        sig { params(name: String, account_id: String).returns(T::Hash[String, T.untyped]) }
        def create_vault(name, account_id:)
          record(
            json_command!(%W[op vault create #{name} --format=json --account #{account_id}]),
            "作成した1Password vault"
          )
        end

        sig { params(vault_id: String, account_id: String).returns(T::Array[T::Hash[String, T.untyped]]) }
        def items(vault_id:, account_id:)
          records(
            json_command!(%W[op item list --include-archive --format=json --vault #{vault_id} --account #{account_id}]),
            "1Password item"
          )
        end

        sig { params(item_id: String, vault_id: String, account_id: String).returns(T::Hash[String, T.untyped]) }
        def item(item_id, vault_id:, account_id:)
          record(
            json_command!(%W[op item get #{item_id} --format=json --vault #{vault_id} --account #{account_id}]),
            "1Password item"
          )
        end

        sig { params(account_id: String).returns(T::Hash[String, T.untyped]) }
        def api_credential_template(account_id:)
          record(
            json_command!(%W[op item template get API\ Credential --account #{account_id}]),
            "1Password item template"
          )
        end

        sig do
          params(
            item: T::Hash[String, T.untyped],
            item_id: T.nilable(String),
            vault_id: String,
            account_id: String
          ).returns(T::Hash[String, T.untyped])
        end
        def save_item(item, item_id:, vault_id:, account_id:)
          command = if item_id
            %W[op item edit #{item_id} --format=json --vault #{vault_id} --account #{account_id}]
          else
            %W[op item create --format=json --vault #{vault_id} --account #{account_id} -]
          end
          record(json_command!(command, stdin_data: JSON.generate(item)), "保存した1Password item")
        end

        sig { params(name: String, vault_name: String, account_id: String).returns(String) }
        def create_service_account(name, vault_name:, account_id:)
          command!(
            [
              "op", "service-account", "create", name,
              "--vault", "#{vault_name}:read_items",
              "--raw", "--account", account_id
            ],
            sensitive: true
          ).strip
        end

        private

        sig do
          params(
            command: T::Array[String],
            stdin_data: T.nilable(String),
            sensitive: T::Boolean
          ).returns(String)
        end
        def command!(command, stdin_data: nil, sensitive: false)
          result = @runner.capture(command, environment: {}, stdin_data:)
          return result.stdout if result.success

          sensitive ||= !stdin_data.nil? || command.first(2) == %w[op item]
          detail = sensitive ? "" : [result.stdout, result.stderr].map(&:strip).reject(&:empty?).join("\n")
          detail = "exit status #{result.exitstatus}" if detail.empty?
          raise Error, "1Password CLI commandに失敗しました: #{detail}"
        end

        sig { params(command: T::Array[String], stdin_data: T.nilable(String)).returns(T.untyped) }
        def json_command!(command, stdin_data: nil)
          JSON.parse(command!(command, stdin_data:))
        rescue JSON::ParserError
          raise Error, "1Password CLIのJSON応答が不正です"
        end

        sig { params(value: T.untyped, label: String).returns(T::Hash[String, T.untyped]) }
        def record(value, label)
          raise Error, "#{label}応答が不正です" unless value.is_a?(Hash)

          value
        end

        sig { params(value: T.untyped, label: String).returns(T::Array[T::Hash[String, T.untyped]]) }
        def records(value, label)
          raise Error, "#{label}一覧応答が不正です" unless value.is_a?(Array)

          value.map { |entry| record(entry, label) }
        end
      end
    end
  RUBY

  create_file "lib/deployment/kamal_secrets_writer.rb", <<~'RUBY', force: true
    # typed: strict
    # frozen_string_literal: true

    require "fileutils"
    require "pathname"
    require "shellwords"
    require "sorbet-runtime"
    require "stringio"
    require "tempfile"

    module Deployment
      class KamalSecretsWriter
        extend T::Sig

        DEPLOY_SECRET_FIELDS = %w[CF_ACCOUNT_ID LITESTREAM_R2_BUCKET R2_ACCESS_KEY R2_SECRET_KEY].freeze

        sig { params(root: Pathname, output: T.any(IO, StringIO)).void }
        def initialize(root:, output: $stdout)
          @root = root
          @output = output
        end

        sig { params(destination: String, account_id: String, vault_id: String, item_id: String).void }
        def write(destination:, account_id:, vault_id:, item_id:)
          path = @root.join(".kamal/secrets.#{destination}")
          FileUtils.mkdir_p(path.dirname)
          account = Shellwords.escape(account_id)
          source = Shellwords.escape("#{vault_id}/#{item_id}")
          content = <<~SECRETS
            R2_SECRETS=$(bin/kamal secrets fetch --adapter 1password --account #{account} --from #{source} #{DEPLOY_SECRET_FIELDS.join(" ")})
            #{DEPLOY_SECRET_FIELDS.map { |name| "#{name}=$(bin/kamal secrets extract #{name} $R2_SECRETS)" }.join("\n")}
          SECRETS
          Tempfile.create(["secrets-#{destination}", ".tmp"], path.dirname.to_s) do |file|
            file.write(content)
            file.flush
            file.fsync
            File.chmod(0o600, file.path)
            File.rename(file.path, path)
          end
          @output.puts "Kamal secret参照を生成しました: #{path.relative_path_from(@root)}"
        end
      end
    end
  RUBY

  configurator = <<~RUBY
    # typed: strict
    # frozen_string_literal: true

    require "active_support/core_ext/enumerable"
    require "digest"
    require "fileutils"
    require "gum"
    require "json"
    require "net/http"
    require "pathname"
    require "shellwords"
    require "sorbet-runtime"
    require "stringio"
    require "tempfile"
    require "uri"
    require "deployment/command_runner"
    require "deployment/cloudflare_client"
    require "deployment/kamal_secrets_writer"
    require "deployment/one_password_client"

    module Deployment
      class Configurator
        extend T::Sig

        APP_ID = #{app_id.inspect}
  RUBY
  configurator << <<~'RUBY'
        DESTINATIONS = %w[production staging].freeze
        DEPLOY_SECRET_FIELDS = %w[CF_ACCOUNT_ID LITESTREAM_R2_BUCKET R2_ACCESS_KEY R2_SECRET_KEY].freeze
        BUCKET_PATTERN = /\A[a-z0-9](?:[a-z0-9-]*[a-z0-9])?\z/
        INITIAL_TOKEN_ENV = "CLOUDFLARE_INITIAL_API_TOKEN"
        INITIAL_TOKEN_TEMPLATE_DOC_URL = "https://developers.cloudflare.com/fundamentals/api/how-to/account-owned-token-template/"
        INITIAL_TOKEN_ACCOUNT_DOC_URL = "https://developers.cloudflare.com/fundamentals/api/get-started/account-owned-tokens/"
        INITIAL_TOKEN_PERMISSION_GROUP_NAME = "Account API Tokens Write"
        ACCOUNT_SCOPE = "com.cloudflare.api.account"
        R2_PERMISSION_GROUP_NAME = "Workers R2 Storage Bucket Item Write"
        R2_BUCKET_SCOPE = "com.cloudflare.edge.r2.bucket"
        R2_ITEM_FIELD_TYPES = T.let(
          {
            "CLOUDFLARE_R2_API_TOKEN" => "CONCEALED",
            "CF_ACCOUNT_ID" => "STRING",
            "LITESTREAM_R2_BUCKET" => "STRING",
            "R2_ACCESS_KEY" => "CONCEALED",
            "R2_SECRET_KEY" => "CONCEALED"
          }.freeze,
          T::Hash[String, String]
        )
        TOKEN_NAME_MAX_BYTES = 120
        SERVICE_ACCOUNT_TYPE = "SERVICE_ACCOUNT"
        ACTIVE_STATE = "ACTIVE"

        sig do
          params(
            root: Pathname,
            prompt: T.untyped,
            runner: T.untyped,
            output: T.any(IO, StringIO),
            environment: T::Hash[String, String],
            terminal: T.nilable(T.any(IO, StringIO)),
            cloudflare_client: T.untyped
          ).void
        end
        def initialize(
          root: Pathname.pwd,
          prompt: Gum,
          runner: CommandRunner.new,
          output: $stdout,
          environment: ENV.to_h,
          terminal: nil,
          cloudflare_client: nil
        )
          @root = root
          @prompt = prompt
          @runner = runner
          @output = output
          @environment = environment
          @terminal = terminal
          @cloudflare_client = T.let(
            CloudflareClient.new(
              token: String(environment.fetch(INITIAL_TOKEN_ENV, "")),
              root:,
              runner:,
              api_client: cloudflare_client
            ),
            CloudflareClient
          )
          @one_password = T.let(OnePasswordClient.new(runner:), OnePasswordClient)
          @kamal_secrets_writer = T.let(KamalSecretsWriter.new(root:, output:), KamalSecretsWriter)
        end

        sig { void }
        def run!
          validate_authentication_environment!
          unless present_environment?(INITIAL_TOKEN_ENV)
            print_initial_token_instructions
            return
          end

          validate_dependencies!
          cloudflare = cloudflare_identity
          cloudflare_account = choose_record(cloudflare.fetch("accounts"), "Cloudflare account")
          account_id = record_id(cloudflare_account)
          validate_cloudflare_initial_token!(cloudflare_account)
          destinations = choose_destinations
          one_password_account = choose_one_password_account
          one_password_account_id = record_id(one_password_account)
          one_password_user = validate_human_one_password_user!(one_password_account_id)
          vault_plans = plan_destination_vaults(destinations, one_password_account_id)
          item_plans = plan_destination_items(destinations, one_password_account_id, vault_plans)

          buckets = bucket_names(destinations)
          existing_buckets = existing_buckets(account_id, buckets.values)
          permission_group = r2_permission_group(account_id)
          cloudflare_tokens = cloudflare_api.tokens(account_id)
          token_plans = T.let({}, T::Hash[String, T::Hash[String, T.untyped]])
          destinations.each do |destination|
            r2_plan = plan_r2_credentials(
              destination,
              account_id:,
              bucket: buckets.fetch(destination),
              permission_group:,
              cloudflare_tokens:,
              item_plan: item_plans.fetch(destination).fetch("r2")
            )
            token_plans[destination] = T.cast(r2_plan.fetch("token"), T::Hash[String, T.untyped])
            item_plans.fetch(destination)["r2"] = T.cast(r2_plan.fetch("item"), T::Hash[String, T.untyped])
          end

          print_plan(
            cloudflare,
            cloudflare_account,
            one_password_account,
            one_password_user,
            vault_plans,
            destinations,
            buckets,
            existing_buckets,
            item_plans,
            token_plans
          )
          unless @prompt.confirm(
            "この内容でデプロイ用の外部サービスと資格情報を構成しますか？",
            default: false,
            affirmative: "実行",
            negative: "中止"
          )
            @output.puts "中止しました。1Password、R2、Cloudflare API token、Kamal secret参照は変更していません。"
            return
          end

          applied = destinations.all? do |destination|
            vault_plan = vault_plans.fetch(destination)
            vault = apply_vault_plan(vault_plan, one_password_account_id)
            service_account_plan = item_plans.fetch(destination).fetch("service_account")
            unless apply_service_account_plan(
              service_account_plan,
              account_id: one_password_account_id,
              vault:
            )
              next false
            end

            bucket = buckets.fetch(destination)
            create_bucket(account_id, bucket) unless existing_buckets.include?(bucket)
            credentials = cloudflare_credentials(
              token_plans.fetch(destination),
              account_id:,
              bucket:
            )
            r2_fields = credentials.merge("CF_ACCOUNT_ID" => account_id, "LITESTREAM_R2_BUCKET" => bucket)
            item_id = apply_r2_item_plan(
              item_plans.fetch(destination).fetch("r2"),
              account_id: one_password_account_id,
              vault_id: record_id(vault),
              fields: r2_fields,
              concealed_fields: %w[CLOUDFLARE_R2_API_TOKEN R2_ACCESS_KEY R2_SECRET_KEY]
            )
            next false unless item_id

            @kamal_secrets_writer.write(
              destination:,
              account_id: one_password_account_id,
              vault_id: record_id(vault),
              item_id:
            )
            true
          end
          return unless applied

          @output.puts "デプロイ設定が完了しました。デプロイ時は bin/kamal deploy -d production|staging を使用してください。"
        end

        private

        sig { void }
        def validate_dependencies!
          @cloudflare_client.validate_dependency!
          @one_password.version
        end

        sig { void }
        def validate_authentication_environment!
          configured = %w[OP_SERVICE_ACCOUNT_TOKEN OP_CONNECT_HOST OP_CONNECT_TOKEN].select do |name|
            present_environment?(name)
          end
          return if configured.empty?

          raise Error,
            "1Passwordの設定操作は人間ユーザーで実行してください。次の環境変数を外して再実行してください: #{configured.join(", ")}"
        end

        sig { params(fields: T::Hash[String, String]).void }
        def reveal_credentials(fields)
          terminal = @terminal
          opened = false
          unless terminal
            terminal = File.open("/dev/tty", "w")
            opened = true
          end
          terminal.puts JSON.pretty_generate(fields)
        rescue SystemCallError => error
          raise Error, "資格情報を端末へ表示できませんでした: #{error.message}"
        ensure
          terminal.close if opened
        end

        sig { void }
        def print_initial_token_instructions
          @output.puts "#{INITIAL_TOKEN_ENV}が設定されていません。"
          @output.puts "対象accountのSuper Administratorで、Account API Tokens: Edit (API: #{INITIAL_TOKEN_PERMISSION_GROUP_NAME})だけを持つaccount-owned Initial Tokenを次のURLから作成してください:"
          @output.puts self.class.initial_token_template_url(APP_ID)
          @output.puts "作成確認画面で対象accountと権限が一致することを確認してください。"
          @output.puts "作成後、#{INITIAL_TOKEN_ENV}を設定して再実行してください。"
          @output.puts "参照: #{INITIAL_TOKEN_TEMPLATE_DOC_URL}"
          @output.puts "参照: #{INITIAL_TOKEN_ACCOUNT_DOC_URL}"
        end

        sig { returns(T.untyped) }
        def cloudflare_api
          @cloudflare_client
        end

        sig { params(name: String).returns(T::Boolean) }
        def present_environment?(name)
          value = @environment[name]
          value.is_a?(String) && !value.strip.empty?
        end

        sig { returns(T::Array[String]) }
        def choose_destinations
          selected = @prompt.choose(
            DESTINATIONS,
            header: "構成するKamal destination",
            selected: DESTINATIONS,
            no_limit: true
          )
          unless selected.is_a?(Array) && selected.any? && (selected - DESTINATIONS).empty?
            raise Error, "productionまたはstagingを1つ以上選択してください"
          end

          DESTINATIONS.select { |destination| selected.include?(destination) }
        end

        sig { returns(T::Hash[String, T.untyped]) }
        def choose_one_password_account
          choose_record(@one_password.accounts, "1Password account")
        end

        sig { params(account_id: String).returns(T::Hash[String, T.untyped]) }
        def validate_human_one_password_user!(account_id)
          identity = @one_password.current_user(account_id)
          raise Error, "1Password service accountでは設定できません。人間ユーザーでログインしてください" if identity["type"] == SERVICE_ACCOUNT_TYPE
          raise Error, "1Passwordユーザーがactiveではありません" unless identity["state"] == ACTIVE_STATE

          identity
        end

        sig { returns(T::Hash[String, T.untyped]) }
        def cloudflare_identity
          @cloudflare_client.identity
        end

        sig { params(account: T::Hash[String, T.untyped]).void }
        def validate_cloudflare_initial_token!(account)
          account_id = record_id(account)
          verification = cloudflare_api.verify_token(account_id)
          token_id = verification["id"]
          unless token_id.is_a?(String) && !token_id.empty? && verification["status"] == "active"
            raise_initial_token_error(account, "tokenがactiveではないか、token IDを取得できません")
          end

          permission_group = initial_token_permission_group(account_id)
          token = cloudflare_api.token_details(account_id, token_id)
          unless token["id"] == token_id && token["status"] == "active"
            raise_initial_token_error(account, "検証結果とtoken詳細が一致しません")
          end
          unless initial_token_policy_matches?(token["policies"], account_id, record_id(permission_group))
            raise_initial_token_error(
              account,
              "Account API Tokens: Edit (API: #{INITIAL_TOKEN_PERMISSION_GROUP_NAME})だけを対象accountへ許可してください"
            )
          end
        rescue CloudflareClient::RequestError => error
          raise unless [401, 403].include?(error.status)

          code_detail = error.codes.empty? ? "HTTP #{error.status}" : "HTTP #{error.status}, code: #{error.codes.join(", ")}"
          raise_initial_token_error(account, "Cloudflare APIに拒否されました (#{code_detail})")
        end

        sig { params(account_id: String).returns(T::Hash[String, T.untyped]) }
        def initial_token_permission_group(account_id)
          records = cloudflare_api.permission_groups(account_id, name: INITIAL_TOKEN_PERMISSION_GROUP_NAME)
          matches = records.select do |record|
            record["name"] == INITIAL_TOKEN_PERMISSION_GROUP_NAME &&
              record["scopes"].is_a?(Array) &&
              record.fetch("scopes").include?(ACCOUNT_SCOPE)
          end
          return matches.fetch(0) if matches.one?

          reason = matches.empty? ? "permission groupが見つかりません" : "permission groupが複数あります"
          raise Error, "Cloudflare #{INITIAL_TOKEN_PERMISSION_GROUP_NAME} #{reason} (#{ACCOUNT_SCOPE})"
        end

        sig do
          params(
            policies: T.untyped,
            account_id: String,
            permission_group_id: String
          ).returns(T::Boolean)
        end
        def initial_token_policy_matches?(policies, account_id, permission_group_id)
          return false unless policies.is_a?(Array) && policies.length == 1

          policy = policies.fetch(0)
          return false unless policy.is_a?(Hash) && policy["effect"] == "allow"
          return false unless policy["resources"] == { "#{ACCOUNT_SCOPE}.#{account_id}" => "*" }

          groups = policy["permission_groups"]
          return false unless groups.is_a?(Array) && groups.length == 1

          group = groups.fetch(0)
          group.is_a?(Hash) && group["id"] == permission_group_id
        end

        sig { params(account: T::Hash[String, T.untyped], reason: String).returns(T.noreturn) }
        def raise_initial_token_error(account, reason)
          account_label = "#{record_name(account)} (#{record_id(account)})"
          raise Error, <<~MESSAGE.strip
            #{INITIAL_TOKEN_ENV}を対象Cloudflare accountで使用できません: #{account_label}
            理由: #{reason}
            対象accountのSuper Administratorで、Account API Tokens: Edit (API: #{INITIAL_TOKEN_PERMISSION_GROUP_NAME})だけを持つaccount-owned tokenを再発行してください:
            #{self.class.initial_token_template_url(APP_ID)}
          MESSAGE
        end

        sig { params(destinations: T::Array[String]).returns(T::Hash[String, String]) }
        def bucket_names(destinations)
          destinations.to_h do |destination|
            initial = self.class.default_bucket_name(APP_ID, destination)
            requested = "#{APP_ID}-db-#{destination}"
            @output.puts "R2 bucket初期値を正規化しました: #{requested} -> #{initial}" unless requested == initial
            value = String(@prompt.input(header: "#{destination} R2 bucket", value: initial)).strip
            validate_bucket_name!(value)
            [destination, value]
          end
        end

        sig { params(account_id: String, buckets: T::Array[String]).returns(T::Array[String]) }
        def existing_buckets(account_id, buckets)
          @cloudflare_client.existing_buckets(account_id, buckets)
        end

        sig do
          params(
            destinations: T::Array[String],
            account_id: String
          ).returns(T::Hash[String, T::Hash[String, T.untyped]])
        end
        def plan_destination_vaults(destinations, account_id)
          records = @one_password.vaults(account_id)

          destinations.to_h do |destination|
            name = self.class.destination_vault_name(APP_ID, destination)
            matches = records.select { |record| record.is_a?(Hash) && record["name"] == name }
            if matches.length > 1
              details = duplicate_vault_details(name, matches)
              raise Error, "同名の1Password vaultが複数あります。手動で1件へ整理してください:\n#{details.join("\n")}"
            end

            vault = matches.first
            [destination, { "destination" => destination, "name" => name, "record" => vault, "action" => vault ? "reuse" : "create" }]
          end
        end

        sig do
          params(
            name: String,
            records: T::Array[T::Hash[String, T.untyped]]
          ).returns(T::Array[String])
        end
        def duplicate_vault_details(name, records)
          records.map do |record|
            items = record["items"]
            item_count = items.is_a?(Integer) ? items.to_s : "unknown"
            "  #{name} (#{record_id(record)}, items: #{item_count})"
          end
        end

        sig do
          params(
            destinations: T::Array[String],
            account_id: String,
            vault_plans: T::Hash[String, T::Hash[String, T.untyped]]
          ).returns(T::Hash[String, T::Hash[String, T.untyped]])
        end
        def plan_destination_items(destinations, account_id, vault_plans)
          destinations.to_h do |destination|
            vault = vault_plans.fetch(destination).fetch("record")
            items = if vault
              @one_password.items(
                vault_id: record_id(T.cast(vault, T::Hash[String, T.untyped])),
                account_id:
              )
            else
              []
            end
            vault_id = vault ? record_id(T.cast(vault, T::Hash[String, T.untyped])) : nil
            plans = {
              "service_account" => plan_service_account_item(destination, items, account_id:, vault_id:),
              "r2" => plan_item(destination, items, account_id:, vault_id:)
            }
            [destination, plans]
          end
        end

        sig do
          params(
            destination: String,
            items: T.untyped,
            account_id: String,
            vault_id: T.nilable(String)
          ).returns(T::Hash[String, T.untyped])
        end
        def plan_item(destination, items, account_id:, vault_id:)
          raise Error, "1Password item一覧応答が不正です" unless items.is_a?(Array)

          title = "#{APP_ID} Litestream R2 #{destination}"
          matches = items.select { |item| item.is_a?(Hash) && item["title"] == title }
          raise Error, "同名の1Password itemが複数あります: #{title}" if matches.length > 1
          raise Error, "1Password itemがarchive済みです。復元または削除してください: #{title}" if matches.first&.fetch("state", nil) == "ARCHIVED"

          item_id = matches.first&.fetch("id", nil)
          unless item_id.nil? || (item_id.is_a?(String) && !item_id.empty?)
            raise Error, "1Password item IDが不正です: #{title}"
          end
          item = if item_id
            @one_password.item(item_id, vault_id: String(vault_id), account_id:)
          end

          { "title" => title, "id" => item_id, "item" => item }
        end

        sig do
          params(
            destination: String,
            items: T.untyped,
            account_id: String,
            vault_id: T.nilable(String)
          ).returns(T::Hash[String, T.untyped])
        end
        def plan_service_account_item(destination, items, account_id:, vault_id:)
          raise Error, "1Password item一覧応答が不正です" unless items.is_a?(Array)

          title = self.class.service_account_name(APP_ID, destination)
          matches = items.select { |item| item.is_a?(Hash) && item["title"] == title }
          raise Error, "同名のservice account token itemが複数あります: #{title}" if matches.length > 1
          match = matches.first
          return { "title" => title, "id" => nil, "item" => nil, "action" => "create" } unless match

          raise Error, "service account token itemがarchive済みです。復元または削除してください: #{title}" if match["state"] == "ARCHIVED"
          item_id = match["id"]
          raise Error, "service account token item IDが不正です: #{title}" unless item_id.is_a?(String) && !item_id.empty?
          item = @one_password.item(item_id, vault_id: String(vault_id), account_id:)
          category = item["category"] || match["category"]
          unless category == "API_CREDENTIAL"
            raise Error, "service account token itemがAPI Credentialではありません: #{title}"
          end
          service_account_token(item, title)

          { "title" => title, "id" => item_id, "item" => item, "action" => "reuse" }
        end

        sig { params(item: T::Hash[String, T.untyped], title: String).returns(String) }
        def service_account_token(item, title)
          fields = item["fields"]
          raise Error, "service account token item fields応答が不正です: #{title}" unless fields.is_a?(Array)
          matches = fields.select do |field|
            field.is_a?(Hash) && (field["label"] == "OP_SERVICE_ACCOUNT_TOKEN" || field["id"] == "OP_SERVICE_ACCOUNT_TOKEN")
          end
          raise Error, "service account token itemにOP_SERVICE_ACCOUNT_TOKENが複数あります: #{title}" if matches.length > 1
          value = matches.first&.fetch("value", nil)
          unless value.is_a?(String) && !value.empty?
            raise Error, "service account token itemにOP_SERVICE_ACCOUNT_TOKENがありません: #{title}"
          end

          value
        end

        sig do
          params(
            plan: T::Hash[String, T.untyped],
            account_id: String
          ).returns(T::Hash[String, T.untyped])
        end
        def apply_vault_plan(plan, account_id)
          record = plan["record"]
          return record if record.is_a?(Hash)

          name = String(plan.fetch("name"))
          begin
            created = @one_password.create_vault(name, account_id:)
            unless created["name"] == name
              raise Error, "作成した1Password vault応答が不正です: #{name}"
            end
            record_id(created)
            @output.puts "1Password vaultを作成しました: #{name}"
            created
          rescue Error => original_error
            matches = @one_password.vaults(account_id).select do |vault|
              vault["name"] == name
            end
            if matches.one?
              @output.puts "1Password vaultの作成結果を再確認しました: #{name}"
              return matches.fetch(0)
            end
            raise original_error if matches.empty?

            details = duplicate_vault_details(name, matches)
            raise Error, "vault作成結果の確認で同名vaultが複数見つかりました:\n#{details.join("\n")}"
          end
        end

        sig do
          params(
            plan: T::Hash[String, T.untyped],
            account_id: String,
            vault: T::Hash[String, T.untyped]
          ).returns(T::Boolean)
        end
        def apply_service_account_plan(plan, account_id:, vault:)
          return true if plan.fetch("action") == "reuse"

          name = String(plan.fetch("title"))
          token = @one_password.create_service_account(name, vault_name: record_name(vault), account_id:).dup
          if token.empty?
            raise Error,
              "1Password service account tokenが返されませんでした。サービスアカウントを再作成せず、1Password管理画面で状態を確認してください: #{name}"
          end

          item_id = persist_item_with_retry(
            plan,
            account_id:,
            vault_id: record_id(vault),
            fields: { "OP_SERVICE_ACCOUNT_TOKEN" => token },
            concealed_fields: ["OP_SERVICE_ACCOUNT_TOKEN"],
            label: "1Password service account token"
          )
          !item_id.nil?
        ensure
          token&.clear
        end

        sig { params(account_id: String).returns(T::Hash[String, T.untyped]) }
        def r2_permission_group(account_id)
          records = cloudflare_api.permission_groups(account_id, name: R2_PERMISSION_GROUP_NAME)
          matches = records.select do |record|
            record["name"] == R2_PERMISSION_GROUP_NAME &&
              record["scopes"].is_a?(Array) &&
              record.fetch("scopes").include?(R2_BUCKET_SCOPE)
          end
          if matches.empty?
            raise Error, "Cloudflare permission groupが見つかりません: #{R2_PERMISSION_GROUP_NAME} (#{R2_BUCKET_SCOPE})"
          end
          if matches.length > 1
            raise Error, "Cloudflare permission groupが複数あります: #{R2_PERMISSION_GROUP_NAME} (#{R2_BUCKET_SCOPE})"
          end

          permission_group = matches.fetch(0)
          record_id(permission_group)
          permission_group
        end

        sig do
          params(
            destination: String,
            account_id: String,
            bucket: String,
            permission_group: T::Hash[String, T.untyped],
            cloudflare_tokens: T::Array[T::Hash[String, T.untyped]],
            item_plan: T::Hash[String, T.untyped]
          ).returns(T::Hash[String, T.untyped])
        end
        def plan_r2_credentials(destination, account_id:, bucket:, permission_group:, cloudflare_tokens:, item_plan:)
          name = self.class.cloudflare_token_name(APP_ID, destination)
          policy = cloudflare_token_policy(account_id, bucket, record_id(permission_group))
          matches = cloudflare_tokens.select { |token| token["name"] == name }
          raise Error, "同名のCloudflare API tokenが複数あります: #{name}" if matches.length > 1
          if matches.empty?
            if item_plan["id"] || item_plan["item"].is_a?(Hash)
              raise Error, "Cloudflare API tokenがありませんが、対応する1Password itemが存在します: #{name}"
            end

            return {
              "token" => { "name" => name, "action" => "create", "policy" => policy },
              "item" => item_plan.merge("action" => "create")
            }
          end

          token = matches.fetch(0)
          raise Error, "Cloudflare API tokenがactiveではありません: #{name}" unless token["status"] == "active"
          unless cloudflare_token_policy_matches?(token["policies"], policy)
            raise Error, "Cloudflare API tokenの権限またはbucketが期待値と一致しません: #{name}"
          end

          item = item_plan["item"]
          unless item.is_a?(Hash)
            raise Error, "Cloudflare API tokenは存在しますが、対応する1Password itemがありません: #{name}"
          end
          credentials = r2_item_fields(item, name)
          token_id = token["id"]
          unless token_id.is_a?(String) && !token_id.empty? && credentials.fetch("R2_ACCESS_KEY") == token_id
            raise Error, "Cloudflare API token IDと1PasswordのR2_ACCESS_KEYが一致しません: #{name}"
          end
          unless Digest::SHA256.hexdigest(credentials.fetch("CLOUDFLARE_R2_API_TOKEN")) == credentials.fetch("R2_SECRET_KEY")
            raise Error, "1PasswordのCloudflare API tokenとR2_SECRET_KEYが一致しません: #{name}"
          end
          unless credentials.fetch("CF_ACCOUNT_ID") == account_id
            raise Error, "Cloudflare account IDと1PasswordのCF_ACCOUNT_IDが一致しません: #{name}"
          end
          unless credentials.fetch("LITESTREAM_R2_BUCKET") == bucket
            raise Error, "Cloudflare API tokenのbucketと1PasswordのLITESTREAM_R2_BUCKETが一致しません: #{name}"
          end

          {
            "token" => { "name" => name, "action" => "reuse", "policy" => policy, "credentials" => credentials },
            "item" => item_plan.merge("action" => "reuse")
          }
        end

        sig { params(account_id: String, bucket: String, permission_group_id: String).returns(T::Hash[String, T.untyped]) }
        def cloudflare_token_policy(account_id, bucket, permission_group_id)
          {
            "effect" => "allow",
            "resources" => {
              "#{R2_BUCKET_SCOPE}.#{account_id}_default_#{bucket}" => "*"
            },
            "permission_groups" => [{ "id" => permission_group_id }]
          }
        end

        sig { params(actual: T.untyped, expected: T::Hash[String, T.untyped]).returns(T::Boolean) }
        def cloudflare_token_policy_matches?(actual, expected)
          return false unless actual.is_a?(Array) && actual.length == 1

          policy = actual.fetch(0)
          return false unless policy.is_a?(Hash)
          return false unless policy["effect"] == expected.fetch("effect")
          return false unless policy["resources"] == expected.fetch("resources")

          permission_groups = policy["permission_groups"]
          expected_groups = expected.fetch("permission_groups")
          return false unless permission_groups.is_a?(Array) && permission_groups.length == 1

          permission_group = permission_groups.fetch(0)
          expected_group = T.cast(expected_groups, T::Array[T::Hash[String, T.untyped]]).fetch(0)
          permission_group.is_a?(Hash) && permission_group["id"] == expected_group.fetch("id")
        end

        sig { params(item: T::Hash[String, T.untyped], token_name: String).returns(T::Hash[String, String]) }
        def r2_item_fields(item, token_name)
          unless item["category"] == "API_CREDENTIAL"
            raise Error, "Cloudflare API tokenの1Password itemがAPI Credentialではありません: #{token_name}"
          end

          fields = item["fields"]
          raise Error, "1Password item fields応答が不正です: #{token_name}" unless fields.is_a?(Array)

          credentials = T.let({}, T::Hash[String, String])
          R2_ITEM_FIELD_TYPES.each do |name, expected_type|
            matches = fields.select do |field|
              field.is_a?(Hash) && (field["label"] == name || field["id"] == name)
            end
            raise Error, "1Password itemに#{name}が複数あります: #{token_name}" if matches.length > 1

            field = matches.first
            value = field&.fetch("value", nil)
            unless value.is_a?(String) && !value.empty?
              raise Error, "Cloudflare API tokenは存在しますが、1Password itemに#{name}がありません: #{token_name}"
            end
            unless field&.fetch("type", nil) == expected_type
              raise Error, "1Password itemの#{name} field typeが一致しません: #{token_name} (期待: #{expected_type})"
            end
            credentials[name] = value
          end
          credentials
        end

        sig do
          params(
            cloudflare: T::Hash[String, T.untyped],
            cloudflare_account: T::Hash[String, T.untyped],
            one_password_account: T::Hash[String, T.untyped],
            one_password_user: T::Hash[String, T.untyped],
            vault_plans: T::Hash[String, T::Hash[String, T.untyped]],
            destinations: T::Array[String],
            buckets: T::Hash[String, String],
            existing_buckets: T::Array[String],
            item_plans: T::Hash[String, T::Hash[String, T.untyped]],
            token_plans: T::Hash[String, T::Hash[String, T.untyped]]
          ).void
        end
        def print_plan(cloudflare, cloudflare_account, one_password_account, one_password_user, vault_plans, destinations, buckets, existing_buckets, item_plans, token_plans)
          user = cloudflare["user"]
          email = user.is_a?(Hash) ? user["email"] : nil
          @output.puts "Cloudflare login: #{email || "unknown"} (#{cloudflare.fetch("authType", "unknown")})"
          @output.puts "Cloudflare account: #{record_name(cloudflare_account)} (#{record_id(cloudflare_account)})"
          @output.puts "1Password account: #{record_name(one_password_account)} (#{record_id(one_password_account)})"
          @output.puts "1Password user: #{record_name(one_password_user)} (#{record_id(one_password_user)})"
          @output.puts "適用予定:"
          destinations.each do |destination|
            vault_plan = vault_plans.fetch(destination)
            bucket = buckets.fetch(destination)
            bucket_action = existing_buckets.include?(bucket) ? "既存を使用" : "新規作成"
            destination_items = item_plans.fetch(destination)
            r2_item_plan = destination_items.fetch("r2")
            service_account_plan = destination_items.fetch("service_account")
            item_action = case r2_item_plan.fetch("action")
            when "reuse" then "既存を使用"
            when "create" then "新規作成"
            else raise Error, "1Password itemの処理計画が不正です: #{r2_item_plan.fetch("title")}"
            end
            token_plan = token_plans.fetch(destination)
            token_action = token_plan.fetch("action") == "reuse" ? "既存を使用" : "新規作成"
            vault_record = vault_plan["record"]
            vault_identity = if vault_record.is_a?(Hash)
              "#{record_name(vault_record)} (#{record_id(vault_record)}, 既存を使用)"
            else
              "#{vault_plan.fetch("name")} (新規作成)"
            end
            service_account_action = service_account_plan.fetch("action") == "reuse" ? "既存を使用" : "新規作成"
            @output.puts "  #{destination}: 1Password vault=#{vault_identity}"
            @output.puts "  #{destination}: service account=#{service_account_plan.fetch("title")} (#{service_account_action}, read_items)"
            @output.puts "  #{destination}: service account token item=#{service_account_plan.fetch("title")} (#{service_account_action})"
            @output.puts "  #{destination}: bucket=#{bucket} (#{bucket_action}), 1Password item=#{r2_item_plan.fetch("title")} (#{item_action})"
            @output.puts "  #{destination}: Cloudflare API token=#{token_plan.fetch("name")} (#{token_action}, Workers R2 Storage Bucket Item Write)"
            @output.puts "    .kamal/secrets.#{destination}: 1Password ID参照を生成"
          end
        end

        sig { params(account_id: String, bucket: String).void }
        def create_bucket(account_id, bucket)
          @cloudflare_client.create_bucket(account_id, bucket)
          @output.puts "R2 bucketを作成しました: #{bucket}"
        end

        sig do
          params(
            plan: T::Hash[String, T.untyped],
            account_id: String,
            bucket: String
          ).returns(T::Hash[String, String])
        end
        def cloudflare_credentials(plan, account_id:, bucket:)
          return T.cast(plan.fetch("credentials"), T::Hash[String, String]) if plan.fetch("action") == "reuse"

          created = cloudflare_api.create_token(
            account_id,
            name: String(plan.fetch("name")),
            policy: T.cast(plan.fetch("policy"), T::Hash[String, T.untyped])
          )
          unless created["name"] == plan.fetch("name") && created["status"] == "active"
            raise Error, "作成したCloudflare API tokenのnameまたはstatusが一致しません: #{plan.fetch("name")}"
          end
          unless cloudflare_token_policy_matches?(created["policies"], T.cast(plan.fetch("policy"), T::Hash[String, T.untyped]))
            raise Error, "作成したCloudflare API tokenの権限またはbucketが一致しません: #{plan.fetch("name")}"
          end

          token_id = created["id"]
          token_value = created["value"]
          unless token_id.is_a?(String) && !token_id.empty? && token_value.is_a?(String) && !token_value.empty?
            raise Error, "作成したCloudflare API tokenのIDまたは値を取得できません: #{plan.fetch("name")}"
          end
          expected_resource = "#{R2_BUCKET_SCOPE}.#{account_id}_default_#{bucket}"
          resources = T.cast(plan.fetch("policy"), T::Hash[String, T.untyped]).fetch("resources")
          unless resources.is_a?(Hash) && resources.keys == [expected_resource]
            raise Error, "Cloudflare API tokenのbucket resourceが一致しません: #{plan.fetch("name")}"
          end

          {
            "CLOUDFLARE_R2_API_TOKEN" => token_value,
            "R2_ACCESS_KEY" => token_id,
            "R2_SECRET_KEY" => Digest::SHA256.hexdigest(token_value)
          }
        end

        sig do
          params(
            plan: T::Hash[String, T.untyped],
            account_id: String,
            vault_id: String,
            fields: T::Hash[String, String],
            concealed_fields: T::Array[String]
          ).returns(T.nilable(String))
        end
        def apply_r2_item_plan(plan, account_id:, vault_id:, fields:, concealed_fields:)
          case plan.fetch("action")
          when "reuse"
            item_id = plan.fetch("id")
            unless item_id.is_a?(String) && !item_id.empty?
              raise Error, "再利用する1Password item IDが不正です: #{plan.fetch("title")}"
            end
            return item_id
          when "create"
            # Continue to the one-time credential persistence path below.
          else
            raise Error, "1Password itemの処理計画が不正です: #{plan.fetch("title")}"
          end

          persist_item_with_retry(
            plan,
            account_id:,
            vault_id:,
            fields:,
            concealed_fields:,
            label: "Cloudflare API token"
          )
        end

        sig do
          params(
            plan: T::Hash[String, T.untyped],
            account_id: String,
            vault_id: String,
            fields: T::Hash[String, String],
            concealed_fields: T::Array[String]
          ).returns(String)
        end
        def upsert_item(plan, account_id:, vault_id:, fields:, concealed_fields:)
          item_id = plan.fetch("id")
          item = if item_id
            plan.fetch("item")
          else
            @one_password.api_credential_template(account_id:)
          end
          raise Error, "1Password item応答が不正です" unless item.is_a?(Hash)

          item["title"] = plan.fetch("title")
          current_fields = item.fetch("fields", [])
          raise Error, "1Password item fields応答が不正です" unless current_fields.is_a?(Array)
          item["fields"] = current_fields.reject do |field|
            field.is_a?(Hash) && fields.key?(field["label"] || field["id"])
          end
          fields.each do |name, value|
            item.fetch("fields") << {
              "id" => name,
              "label" => name,
              "type" => concealed_fields.include?(name) ? "CONCEALED" : "STRING",
              "value" => value
            }
          end

          saved = @one_password.save_item(item, item_id: T.cast(item_id, T.nilable(String)), vault_id:, account_id:)
          saved_id = saved["id"] if saved.is_a?(Hash)
          raise Error, "保存した1Password itemのIDを取得できません" unless saved_id.is_a?(String) && !saved_id.empty?

          saved_id
        end

        sig do
          params(
            plan: T::Hash[String, T.untyped],
            account_id: String,
            vault_id: String,
            fields: T::Hash[String, String],
            concealed_fields: T::Array[String],
            label: String
          ).returns(T.nilable(String))
        end
        def persist_item_with_retry(plan, account_id:, vault_id:, fields:, concealed_fields:, label:)
          loop do
            begin
              return upsert_item(plan, account_id:, vault_id:, fields:, concealed_fields:)
            rescue Error => error
              reconciled_id = reconcile_saved_item(plan, account_id:, vault_id:, fields:)
              return reconciled_id if reconciled_id

              @output.puts "#{label}の1Password保存に失敗しました: #{error.message}"
              next if @prompt.confirm(
                "1Passwordへの保存を再試行しますか？",
                default: true,
                affirmative: "再試行",
                negative: "中止"
              )

              if @prompt.confirm(
                "未保存の資格情報を端末へ一度だけ表示して終了しますか？",
                default: false,
                affirmative: "表示して終了",
                negative: "再試行へ戻る"
              )
                reveal_credentials(fields)
                @output.puts "資格情報を#{plan.fetch("title")}へ手動保存してから再実行してください。"
                return nil
              end
            end
          end
        end

        sig do
          params(
            plan: T::Hash[String, T.untyped],
            account_id: String,
            vault_id: String,
            fields: T::Hash[String, String]
          ).returns(T.nilable(String))
        end
        def reconcile_saved_item(plan, account_id:, vault_id:, fields:)
          records = @one_password.items(vault_id:, account_id:)

          title = String(plan.fetch("title"))
          matches = records.select { |item| item.is_a?(Hash) && item["title"] == title }
          raise Error, "保存確認で同名の1Password itemが複数見つかりました: #{title}" if matches.length > 1
          match = matches.first
          return nil unless match
          raise Error, "保存確認で1Password itemがarchive済みです: #{title}" if match["state"] == "ARCHIVED"

          item_id = match["id"]
          raise Error, "保存確認で1Password item IDが不正です: #{title}" unless item_id.is_a?(String) && !item_id.empty?
          item = @one_password.item(item_id, vault_id:, account_id:)
          return nil unless item_fields_match?(item, fields)

          item_id
        end

        sig { params(item: T::Hash[String, T.untyped], expected: T::Hash[String, String]).returns(T::Boolean) }
        def item_fields_match?(item, expected)
          fields = item["fields"]
          return false unless fields.is_a?(Array)

          expected.all? do |name, value|
            matches = fields.select do |field|
              field.is_a?(Hash) && (field["label"] == name || field["id"] == name)
            end
            matches.one? && matches.first&.fetch("value", nil) == value
          end
        end

        sig { params(records: T.untyped, header: String).returns(T::Hash[String, T.untyped]) }
        def choose_record(records, header)
          raise Error, "#{header}の候補がありません" unless records.is_a?(Array) && records.any?
          typed = records.map do |record|
            raise Error, "#{header}の応答が不正です" unless record.is_a?(Hash)

            record
          end
          return typed.fetch(0) if typed.one?

          labels = typed.to_h { |record| ["#{record_name(record)} (#{record_id(record)})", record] }
          choice = @prompt.choose(labels.keys, header:, selected: [labels.keys.fetch(0)])
          labels.fetch(String(choice))
        end

        sig { params(record: T::Hash[String, T.untyped]).returns(String) }
        def record_id(record)
          value = record["id"] || record["uuid"] || record["account_uuid"] || record["user_uuid"]
          raise Error, "account/vault IDを取得できません" unless value.is_a?(String) && !value.empty?

          value
        end

        sig { params(record: T::Hash[String, T.untyped]).returns(String) }
        def record_name(record)
          value = record["name"] || record["title"] || record["account_name"] || record["email"] || record["url"]
          value.is_a?(String) && !value.empty? ? value : "unknown"
        end

        sig { params(value: String).void }
        def validate_bucket_name!(value)
          return if value.bytesize.between?(3, 63) && BUCKET_PATTERN.match?(value)

          raise Error, "R2 bucket名は3〜63文字の小文字英数字とハイフンのみで、先頭・末尾は英数字にしてください: #{value.inspect}"
        end

        class << self
          extend T::Sig

          sig { params(app_id: String).returns(String) }
          def normalized_app_id(app_id)
            normalized = app_id.downcase.gsub(/[^a-z0-9]+/, "-").gsub(/\A-+|-+\z/, "")
            normalized.empty? ? "app" : normalized
          end

          sig { params(app_id: String, destination: String).returns(String) }
          def service_account_name(app_id, destination)
            "deploy:#{normalized_app_id(app_id)}:#{destination}"
          end

          sig { params(app_id: String, destination: String).returns(String) }
          def destination_vault_name(app_id, destination)
            "#{normalized_app_id(app_id)}-#{destination}"
          end

          sig { params(app_id: String, destination: String).returns(String) }
          def default_bucket_name(app_id, destination)
            suffix = "-db-#{destination}"
            normalized = normalized_app_id(app_id)
            normalized = normalized.byteslice(0, 63 - suffix.bytesize).to_s.gsub(/-+\z/, "")
            "#{normalized}#{suffix}"
          end

          sig { params(app_id: String, destination: String).returns(String) }
          def cloudflare_token_name(app_id, destination)
            bounded_token_name(app_id, "-r2-#{destination}")
          end

          sig { params(app_id: String).returns(String) }
          def initial_token_template_url(app_id)
            permissions = URI.encode_www_form_component(
              JSON.generate([{ "key" => "account_api_tokens", "type" => "edit" }])
            )
            name = URI.encode_www_form_component(bounded_token_name(app_id, "-api-token-creator"))
            "https://dash.cloudflare.com/?to=/:account/api-tokens&permissionGroupKeys=#{permissions}&name=#{name}"
          end

          private

          sig { params(app_id: String, suffix: String).returns(String) }
          def bounded_token_name(app_id, suffix)
            normalized = normalized_app_id(app_id)
            candidate = "#{normalized}#{suffix}"
            return candidate if candidate.bytesize <= TOKEN_NAME_MAX_BYTES

            digest_suffix = "-#{Digest::SHA256.hexdigest(app_id).slice(0, 12)}#{suffix}"
            prefix = normalized.byteslice(0, TOKEN_NAME_MAX_BYTES - digest_suffix.bytesize).to_s.gsub(/-+\z/, "")
            prefix = "app" if prefix.empty?
            "#{prefix}#{digest_suffix}"
          end
        end
      end
    end
  RUBY
  create_file "lib/deployment/configurator.rb", configurator, force: true

  server_setup = <<~RUBY
    # typed: strict
    # frozen_string_literal: true

    require "base64"
    require "fileutils"
    require "gum"
    require "ipaddr"
    require "json"
    require "net/http"
    require "openssl"
    require "pathname"
    require "resolv"
    require "securerandom"
    require "shellwords"
    require "socket"
    require "sorbet-runtime"
    require "stringio"
    require "tempfile"
    require "timeout"
    require "tmpdir"
    require "yaml"
    require "deployment/command_runner"

    module Deployment
      HAS_WORKER = #{VALUES.fetch("active_job") == "solid_queue"}
  RUBY
  server_setup << <<~'RUBY'
      class ServerInstance < T::Struct
        const :id, String
        const :label, String
        const :main_ip, String
        const :v6_main_ip, String
        const :os, String
        const :region, String
      end

      class VultrClient
        extend T::Sig

        sig { params(runner: T.untyped, environment: T::Hash[String, String]).void }
        def initialize(runner:, environment:)
          @runner = runner
          @environment = environment
        end

        sig { void }
        def validate!
          key = @environment["VULTR_API_KEY"]
          raise Error, "VULTR_API_KEYが設定されていません" unless key.is_a?(String) && !key.strip.empty?

          version = @runner.capture(["vultr-cli", "version"])
          raise Error, "vultr-cliを実行できません: #{version.stderr.strip}" unless version.success
          raise Error, "vultr-cli major v3が必要です: #{version.stdout.strip}" unless version.stdout.match?(/\bv?3\./)
        end

        sig { returns(T::Array[ServerInstance]) }
        def eligible_instances
          records = all_instance_records
          instances = records.filter_map { |record| build_instance(record) }
          raise Error, "稼働中のUbuntu LTS x64専用VPSがありません" if instances.empty?

          instances
        end

        private

        sig { returns(T::Array[T::Hash[String, T.untyped]]) }
        def all_instance_records
          records = T.let([], T::Array[T::Hash[String, T.untyped]])
          cursor = T.let(nil, T.nilable(String))
          seen = T.let({}, T::Hash[String, T::Boolean])
          loop do
            command = ["vultr-cli", "instance", "list", "--output=json", "--per-page=500"]
            command << "--cursor=#{cursor}" if cursor
            result = @runner.capture(command, environment: vultr_environment)
            raise Error, "Vultr instance一覧を取得できません: #{result.stderr.strip}" unless result.success

            payload = parse_object(result.stdout, "Vultr instance一覧")
            page = payload["instances"]
            raise Error, "Vultr instance一覧のJSONが不正です" unless page.is_a?(Array)
            page.each do |record|
              raise Error, "Vultr instanceのJSONが不正です" unless record.is_a?(Hash)
              records << T.cast(record, T::Hash[String, T.untyped])
            end

            next_cursor = payload.dig("meta", "links", "next")
            break unless next_cursor.is_a?(String) && !next_cursor.empty?
            raise Error, "Vultr instance一覧のcursorが循環しています" if seen[next_cursor]

            seen[next_cursor] = true
            cursor = next_cursor
          end
          records
        end

        sig { params(value: String, label: String).returns(T::Hash[String, T.untyped]) }
        def parse_object(value, label)
          parsed = JSON.parse(value)
          raise Error, "#{label}のJSONがobjectではありません" unless parsed.is_a?(Hash)

          T.cast(parsed, T::Hash[String, T.untyped])
        rescue JSON::ParserError => error
          raise Error, "#{label}のJSONを解析できません: #{error.message}"
        end

        sig { returns(T::Hash[String, String]) }
        def vultr_environment
          { "VULTR_API_KEY" => String(@environment.fetch("VULTR_API_KEY")) }
        end

        sig { params(record: T::Hash[String, T.untyped]).returns(T.nilable(ServerInstance)) }
        def build_instance(record)
          return nil unless record["status"] == "active"
          return nil unless record["power_status"] == "running"
          return nil unless record["server_status"] == "ok"
          return nil unless Integer(record.fetch("app_id", -1)) == 0

          os = String(record.fetch("os", ""))
          return nil unless os.match?(/\AUbuntu .+ LTS x64\z/i)

          main_ip = String(record.fetch("main_ip", ""))
          return nil unless public_ipv4?(main_ip)

          ServerInstance.new(
            id: String(record.fetch("id")),
            label: String(record.fetch("label", "")),
            main_ip:,
            v6_main_ip: String(record.fetch("v6_main_ip", "")),
            os:,
            region: String(record.fetch("region", ""))
          )
        rescue ArgumentError, KeyError, TypeError
          nil
        end

        sig { params(value: String).returns(T::Boolean) }
        def public_ipv4?(value)
          address = IPAddr.new(value)
          address.ipv4? && !address.private? && !address.loopback? && !address.link_local?
        rescue IPAddr::InvalidAddressError
          false
        end
      end

      class CloudflareRanges
        extend T::Sig

        ENDPOINT = URI("https://api.cloudflare.com/client/v4/ips")

        sig { params(http: T.untyped).void }
        def initialize(http: Net::HTTP)
          @http = http
        end

        sig { returns(T::Array[IPAddr]) }
        def fetch
          response = T.unsafe(@http).get_response(ENDPOINT)
          raise Error, "Cloudflare IP範囲を取得できません: HTTP #{response.code}" unless response.is_a?(Net::HTTPSuccess)

          payload = JSON.parse(T.must(response.body))
          result = payload["result"] if payload.is_a?(Hash) && payload["success"] == true
          raise Error, "Cloudflare IP範囲の応答が不正です" unless result.is_a?(Hash)

          values = [result["ipv4_cidrs"], result["ipv6_cidrs"]].flatten
          raise Error, "Cloudflare IP範囲が空です" unless values.any? && values.all? { |value| value.is_a?(String) }

          T.cast(values, T::Array[String]).map { |value| IPAddr.new(value) }
        rescue JSON::ParserError, IPAddr::InvalidAddressError => error
          raise Error, "Cloudflare IP範囲を解析できません: #{error.message}"
        rescue IOError, OpenSSL::SSL::SSLError, SocketError, SystemCallError, Timeout::Error => error
          raise Error, "Cloudflare IP範囲を取得できません: #{error.message}"
        end
      end

      class DnsValidator
        extend T::Sig

        sig { params(resolver: T.untyped, cloudflare_ranges: T.untyped).void }
        def initialize(resolver: Resolv, cloudflare_ranges: CloudflareRanges.new)
          @resolver = resolver
          @cloudflare_ranges = cloudflare_ranges
        end

        sig { params(hostname: String, instance: ServerInstance).returns(T.nilable(String)) }
        def direct_ipv6!(hostname, instance)
          addresses = resolved_addresses(hostname)
          ipv4 = addresses.select(&:ipv4?).uniq
          expected_ipv4 = IPAddr.new(instance.main_ip)
          raise Error, "#{hostname}のAレコードは#{instance.main_ip}だけにしてください" unless ipv4 == [expected_ipv4]

          ipv6 = addresses.select(&:ipv6?).uniq
          return nil if ipv6.empty?

          raise Error, "VPSに公開IPv6がありませんがAAAAレコードが存在します" if instance.v6_main_ip.empty?
          expected_ipv6 = IPAddr.new(instance.v6_main_ip)
          raise Error, "#{hostname}のAAAAレコードは#{instance.v6_main_ip}だけにしてください" unless ipv6 == [expected_ipv6]

          instance.v6_main_ip
        end

        sig { params(hostname: String).void }
        def cloudflare_proxy!(hostname)
          addresses = resolved_addresses(hostname)
          ranges = @cloudflare_ranges.fetch
          outside = addresses.reject { |address| ranges.any? { |range| range.include?(address) } }
          raise Error, "#{hostname}にはCloudflare proxy外のDNS応答があります: #{outside.join(', ')}" if outside.any?
        end

        private

        sig { params(hostname: String).returns(T::Array[IPAddr]) }
        def resolved_addresses(hostname)
          values = T.unsafe(@resolver).getaddresses(hostname)
          addresses = values.map { |value| IPAddr.new(String(value)) }.uniq
          raise Error, "#{hostname}を名前解決できません" if addresses.empty?

          addresses
        rescue Resolv::ResolvError, IPAddr::InvalidAddressError => error
          raise Error, "#{hostname}のDNSを確認できません: #{error.message}"
        end
      end

      class DestinationConfig
        extend T::Sig

        MANAGED_PATHS = [
          %w[servers web],
          %w[servers worker hosts],
          %w[proxy host],
          %w[proxy run bind_ips],
          %w[env clear APPLICATION_ORIGIN],
          %w[accessories litestream host],
          %w[ssh user]
        ].freeze

        sig { params(path: Pathname).void }
        def initialize(path)
          @path = path
          @raw = T.let(path.read, String)
          @data = T.let(parse_plain_mapping(@raw), T::Hash[String, T.untyped])
        end

        sig { returns(String) }
        attr_reader :raw

        sig { returns(T::Hash[String, T.untyped]) }
        def managed_values
          MANAGED_PATHS.to_h { |path| [path.join("."), dig_path(@data, path)] }
        end

        sig { returns(T.nilable(String)) }
        def web_host
          value = dig_path(@data, %w[servers web])
          return nil if value.nil? || value == []
          unless value.is_a?(Array) && value.one? && value.first.is_a?(String)
            raise Error, "#{@path}のservers.webは空、または単一hostの配列にしてください"
          end

          T.cast(value.first, String)
        end

        sig { params(instance: ServerInstance, hostname: String, ipv6: T::Boolean).returns(T::Hash[String, T.untyped]) }
        def proposed(instance:, hostname:, ipv6:)
          data = T.cast(Marshal.load(Marshal.dump(@data)), T::Hash[String, T.untyped])
          set_path(data, %w[servers web], [instance.main_ip])
          set_path(data, %w[servers worker hosts], [instance.main_ip]) if HAS_WORKER
          set_path(data, %w[proxy host], hostname)
          set_path(data, %w[proxy run bind_ips], ipv6 ? ["0.0.0.0", "::"] : ["0.0.0.0"])
          set_path(data, %w[env clear APPLICATION_ORIGIN], "https://#{hostname}")
          set_path(data, %w[accessories litestream host], instance.main_ip)
          set_path(data, %w[ssh user], "root")
          data
        end

        sig { params(data: T::Hash[String, T.untyped]).void }
        def write!(data)
          Tempfile.create([@path.basename.to_s, ".tmp"], @path.dirname.to_s) do |file|
            file.chmod(0o644)
            file.write(YAML.dump(data, line_width: -1))
            file.flush
            file.fsync
            File.rename(file.path, @path.to_s)
          end
        end

        sig { void }
        def restore!
          Tempfile.create([@path.basename.to_s, ".restore"], @path.dirname.to_s) do |file|
            file.chmod(0o644)
            file.write(@raw)
            file.flush
            file.fsync
            File.rename(file.path, @path.to_s)
          end
        end

        private

        sig { params(raw: String).returns(T::Hash[String, T.untyped]) }
        def parse_plain_mapping(raw)
          if raw.include?("<%") || raw.match?(/(?:^|\s)[&*][A-Za-z0-9_-]+/) || raw.lines.any? { |line| line.match?(/^\s*#|\s+#/) }
            raise Error, "#{@path}にコメント、YAML anchor、またはERBがあるため自動更新できません"
          end
          parsed = YAML.safe_load(raw, permitted_classes: [], permitted_symbols: [], aliases: false)
          parsed = {} if parsed.nil?
          raise Error, "#{@path}のrootはYAML mappingにしてください" unless parsed.is_a?(Hash)
          raise Error, "#{@path}のkeyは文字列にしてください" unless parsed.keys.all? { |key| key.is_a?(String) }

          T.cast(parsed, T::Hash[String, T.untyped])
        rescue Psych::Exception => error
          raise Error, "#{@path}をplain YAMLとして解析できません: #{error.message}"
        end

        sig { params(data: T::Hash[String, T.untyped], path: T::Array[String]).returns(T.untyped) }
        def dig_path(data, path)
          path.reduce(T.let(data, T.untyped)) do |value, key|
            break nil unless value.is_a?(Hash)
            value[key]
          end
        end

        sig { params(data: T::Hash[String, T.untyped], path: T::Array[String], value: T.untyped).void }
        def set_path(data, path, value)
          current = T.let(data, T::Hash[String, T.untyped])
          T.must(path[0...-1]).each do |key|
            child = current[key]
            if child.nil?
              child = {}
              current[key] = child
            end
            raise Error, "#{@path}の#{path.join('.')}と既存値の型が競合しています" unless child.is_a?(Hash)
            current = T.cast(child, T::Hash[String, T.untyped])
          end
          current[path.fetch(-1)] = value
        end
      end

      class SshHardener
        extend T::Sig

        CONFIG_PATH = "/etc/ssh/sshd_config.d/99-rapid-rails-template.conf"
        CONFIG = <<~CONFIG.freeze
          PasswordAuthentication no
          KbdInteractiveAuthentication no
          PubkeyAuthentication yes
          PermitRootLogin prohibit-password
        CONFIG

        sig { params(runner: T.untyped).void }
        def initialize(runner:)
          @runner = runner
        end

        sig { void }
        def validate_client!
          result = @runner.capture(["ssh", "-V"])
          version = [result.stdout, result.stderr].join(" ").strip
          raise Error, "OpenSSH clientを実行できません: #{version}" unless result.success && version.match?(/\bOpenSSH_/)
        end

        sig { params(ip: String, pristine: T::Boolean).void }
        def preflight!(ip, pristine:)
          script = +<<~BASH
            set -euo pipefail
            test "$(id -u)" = 0
            . /etc/os-release
            test "$ID" = ubuntu
            case "$PRETTY_NAME" in *LTS*) ;; *) echo "Ubuntu LTSではありません" >&2; exit 1;; esac
            test "$(uname -m)" = x86_64
          BASH
          if pristine
            script << <<~'BASH'
              if command -v docker >/dev/null 2>&1 && test -n "$(docker ps -aq)"; then
                echo "既存Docker containerがあります" >&2
                exit 1
              fi
              listeners="$(ss -H -ltn | awk '{print $4}' | grep -Ev '(^127\.|^\[?::1\]?|:22$)' || true)"
              if test -n "$listeners"; then
                echo "22番以外の公開TCP待受があります:" >&2
                echo "$listeners" >&2
                exit 1
              fi
            BASH
          end
          result = @runner.capture(ssh_command(ip, control_path: nil, independent: true) + ["bash", "-s"], stdin_data: script)
          raise Error, "SSH事前確認に失敗しました: #{result.stderr.strip}" unless result.success
        end

        sig { params(ip: String).returns(String) }
        def current_config(ip)
          command = "test ! -e #{Shellwords.escape(CONFIG_PATH)} || cat #{Shellwords.escape(CONFIG_PATH)}"
          result = @runner.capture(ssh_command(ip, control_path: nil, independent: true) + ["bash", "-c", command])
          raise Error, "既存SSH設定を取得できません: #{result.stderr.strip}" unless result.success

          result.stdout
        end

        sig { params(ip: String).void }
        def apply!(ip)
          Dir.mktmpdir("rrt-ssh") do |directory|
            socket = File.join(directory, "c")
            target = "root@#{ip}"
            master = @runner.capture(base_ssh + ["-M", "-S", socket, "-fN", target])
            raise Error, "SSH ControlMasterを開始できません: #{master.stderr.strip}" unless master.success

            backup = "/tmp/rapid-rails-ssh-#{SecureRandom.hex(8)}"
            begin
              apply = @runner.capture(master_command(socket, target) + ["bash", "-s"], stdin_data: apply_script(backup))
              unless apply.success
                rollback = @runner.capture(master_command(socket, target) + ["bash", "-s"], stdin_data: rollback_script(backup))
                message = "SSH設定の適用に失敗したため設定を復元しました: #{apply.stderr.strip}"
                message += " / 復元にも失敗しました: #{rollback.stderr.strip}" unless rollback.success
                raise Error, message
              end

              verify = @runner.capture(ssh_command(ip, control_path: nil, independent: true) + ["bash", "-s"], stdin_data: verify_script)
              unless verify.success
                rollback = @runner.capture(master_command(socket, target) + ["bash", "-s"], stdin_data: rollback_script(backup))
                message = "SSH再接続に失敗したため設定を復元しました: #{verify.stderr.strip}"
                message += " / 復元にも失敗しました: #{rollback.stderr.strip}" unless rollback.success
                raise Error, message
              end

              cleanup = "rm -f #{Shellwords.escape(backup)} #{Shellwords.escape("#{backup}.absent")}"
              @runner.capture(master_command(socket, target) + ["bash", "-c", cleanup])
            ensure
              @runner.capture(base_ssh + ["-S", socket, "-O", "exit", target])
            end
          end
        end

        private

        sig { returns(T::Array[String]) }
        def base_ssh
          [
            "ssh", "-p", "22",
            "-o", "BatchMode=yes",
            "-o", "PreferredAuthentications=publickey",
            "-o", "PasswordAuthentication=no",
            "-o", "KbdInteractiveAuthentication=no",
            "-o", "StrictHostKeyChecking=accept-new",
            "-o", "ConnectTimeout=10"
          ]
        end

        sig { params(ip: String, control_path: T.nilable(String), independent: T::Boolean).returns(T::Array[String]) }
        def ssh_command(ip, control_path:, independent:)
          command = base_ssh
          command += ["-o", "ControlMaster=no", "-o", "ControlPath=none"] if independent
          command += ["-S", control_path] if control_path
          command + ["root@#{ip}"]
        end

        sig { params(socket: String, target: String).returns(T::Array[String]) }
        def master_command(socket, target)
          base_ssh + ["-S", socket, target]
        end

        sig { params(backup: String).returns(String) }
        def apply_script(backup)
          target = Shellwords.escape(CONFIG_PATH)
          escaped_backup = Shellwords.escape(backup)
          escaped_absent = Shellwords.escape("#{backup}.absent")
          body = Shellwords.escape(Base64.strict_encode64(CONFIG))
          <<~BASH
            set -euo pipefail
            target=#{target}
            backup=#{escaped_backup}
            absent=#{escaped_absent}
            install -d -m 0755 /etc/ssh/sshd_config.d
            if test -e "$target"; then cp -p "$target" "$backup"; else touch "$absent"; fi
            restore() {
              if test -e "$absent"; then rm -f "$target"; else cp -p "$backup" "$target"; fi
              /usr/sbin/sshd -t && systemctl reload ssh
            }
            trap restore ERR
            printf %s #{body} | base64 --decode > "$target"
            chmod 0644 "$target"
            /usr/sbin/sshd -t
            systemctl reload ssh
            trap - ERR
          BASH
        end

        sig { params(backup: String).returns(String) }
        def rollback_script(backup)
          target = Shellwords.escape(CONFIG_PATH)
          escaped_backup = Shellwords.escape(backup)
          escaped_absent = Shellwords.escape("#{backup}.absent")
          <<~BASH
            set -euo pipefail
            if test -e #{escaped_absent}; then
              rm -f #{target}
            else
              cp -p #{escaped_backup} #{target}
            fi
            /usr/sbin/sshd -t
            systemctl reload ssh
            rm -f #{escaped_backup} #{escaped_absent}
          BASH
        end

        sig { returns(String) }
        def verify_script
          <<~'BASH'
            set -euo pipefail
            output="$(/usr/sbin/sshd -T)"
            grep -qx 'passwordauthentication no' <<<"$output"
            grep -qx 'kbdinteractiveauthentication no' <<<"$output"
            grep -qx 'pubkeyauthentication yes' <<<"$output"
            grep -Eq '^permitrootlogin (prohibit-password|without-password)$' <<<"$output"
          BASH
        end
      end

      class HealthChecker
        extend T::Sig

        class Target < T::Struct
          const :hostname, String
          const :address, T.nilable(String)
        end

        sig { params(output: T.any(IO, StringIO), timeout: Integer, interval: Integer).void }
        def initialize(output:, timeout: 60, interval: 2)
          @output = output
          @timeout = timeout
          @interval = interval
        end

        sig { params(targets: T::Array[T.untyped]).void }
        def wait!(targets)
          deadline = Process.clock_gettime(Process::CLOCK_MONOTONIC) + @timeout
          loop do
            return if targets.all? { |target| healthy?(String(target.hostname), target.address&.to_s) }
            break if Process.clock_gettime(Process::CLOCK_MONOTONIC) >= deadline
            sleep @interval
          end
          labels = targets.map { |target| target.address ? "#{target.hostname}(#{target.address})" : target.hostname }
          raise Error, "HTTPS /upが60秒以内に200を返しませんでした: #{labels.join(', ')}"
        end

        private

        sig { params(hostname: String, address: T.nilable(String)).returns(T::Boolean) }
        def healthy?(hostname, address)
          result = Timeout.timeout(5) do
            tcp = TCPSocket.new(address || hostname, 443)
            context = OpenSSL::SSL::SSLContext.new
            context.set_params
            ssl = OpenSSL::SSL::SSLSocket.new(tcp, context)
            ssl.hostname = hostname
            ssl.sync_close = true
            ssl.connect
            ssl.post_connection_check(hostname)
            ssl.write("GET /up HTTP/1.1\r\nHost: #{hostname}\r\nConnection: close\r\n\r\n")
            status = ssl.gets
            ssl.close
            status.is_a?(String) && status.match?(/\AHTTP\/\d(?:\.\d)? 200\b/)
          end
          result == true
        rescue IOError, SystemCallError, SocketError, Timeout::Error, OpenSSL::SSL::SSLError
          false
        end
      end

      class ServerSetup
        extend T::Sig

        DESTINATIONS = %w[production staging].freeze
        PROVIDERS = ["Vultr"].freeze
        DNS_MODES = ["DNS-only", "Cloudflare proxy"].freeze
        FQDN = /\A(?=.{1,253}\z)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}\z/i

        sig do
          params(
            root: Pathname,
            prompt: T.untyped,
            runner: T.untyped,
            output: T.any(IO, StringIO),
            environment: T::Hash[String, String],
            terminal: T::Boolean,
            vultr: T.untyped,
            dns: T.untyped,
            ssh: T.untyped,
            health: T.untyped
          ).void
        end
        def initialize(
          root: Pathname.pwd,
          prompt: Gum,
          runner: CommandRunner.new,
          output: $stdout,
          environment: ENV.to_h,
          terminal: $stdin.tty? && $stdout.tty?,
          vultr: nil,
          dns: nil,
          ssh: nil,
          health: nil
        )
          @root = root
          @prompt = prompt
          @runner = runner
          @output = output
          @environment = environment
          @terminal = terminal
          @vultr = vultr || VultrClient.new(runner:, environment:)
          @dns = dns || DnsValidator.new
          @ssh = ssh || SshHardener.new(runner:)
          @health = health || HealthChecker.new(output:)
        end

        sig { void }
        def run!
          raise Error, "deployment:setup-serverはTTY上で実行してください" unless @terminal
          @ssh.validate_client!
          @vultr.validate!

          destination = choose_one(DESTINATIONS, "Kamal destination", "production")
          secrets = @root.join(".kamal/secrets.#{destination}")
          unless secrets.file? && !secrets.read.strip.empty?
            raise Error, "#{secrets.relative_path_from(@root)}がありません。先にbin/rails deployment:configureを実行してください"
          end

          provider = choose_one(PROVIDERS, "IaaS", "Vultr")
          raise Error, "未対応のIaaSです: #{provider}" unless provider == "Vultr"
          instance = choose_instance(@vultr.eligible_instances)

          current = DestinationConfig.new(@root.join("config/deploy.#{destination}.yml"))
          hostname = choose_hostname(current)
          dns_mode = choose_one(DNS_MODES, "DNS構成", "DNS-only")
          ipv6_address = T.let(nil, T.nilable(String))
          if dns_mode == "DNS-only"
            ipv6_address = @dns.direct_ipv6!(hostname, instance)
          else
            @dns.cloudflare_proxy!(hostname)
          end

          other_destination = (DESTINATIONS - [destination]).fetch(0)
          other = DestinationConfig.new(@root.join("config/deploy.#{other_destination}.yml"))
          if other.web_host == instance.main_ip
            raise Error, "#{instance.main_ip}は既に#{other_destination}で使用されています"
          end

          previous_host = current.web_host
          pristine = previous_host != instance.main_ip
          @ssh.preflight!(instance.main_ip, pristine:)

          proposed = current.proposed(instance:, hostname:, ipv6: !ipv6_address.nil?)
          confirm_destination_change!(current, proposed, destination) unless current.managed_values == managed_values(proposed)
          confirm_ssh_change!(instance.main_ip)

          @ssh.apply!(instance.main_ip)
          current.write!(proposed)
          validate_kamal_config!(destination, current)

          command = [@root.join("bin/kamal").to_s, "setup", "-d", destination]
          unless @prompt.confirm(
            "Kamal setup（初回デプロイを含む）を実行しますか？",
            default: true,
            affirmative: "実行",
            negative: "後で実行"
          )
            @output.puts "サーバー設定を保存しました。後で次を実行してください: bin/kamal setup -d #{destination}"
            return
          end

          unless @runner.run(command).zero?
            raise Error, "Kamal setupに失敗しました。設定は保持しています。再試行: bin/kamal setup -d #{destination}"
          end

          @health.wait!(health_targets(hostname, instance, ipv6_address:))
          @output.puts "#{destination}のサーバー設定と初回デプロイが完了しました。"
        end

        private

        sig { params(values: T::Array[String], header: String, selected: String).returns(String) }
        def choose_one(values, header, selected)
          choice = @prompt.choose(values, header:, selected: [selected])
          value = String(choice)
          raise Error, "#{header}の選択が不正です" unless values.include?(value)

          value
        end

        sig { params(instances: T::Array[ServerInstance]).returns(ServerInstance) }
        def choose_instance(instances)
          labels = instances.to_h do |instance|
            label = "#{instance.label.empty? ? '(no label)' : instance.label} | #{instance.main_ip} | #{instance.os} | #{instance.region} | #{instance.id}"
            [label, instance]
          end
          choice = @prompt.choose(labels.keys, header: "Vultr VPS", selected: [labels.keys.fetch(0)])
          labels.fetch(String(choice))
        end

        sig { params(config: DestinationConfig).returns(String) }
        def choose_hostname(config)
          current = config.managed_values["proxy.host"]
          initial = current.is_a?(String) ? current : ""
          value = String(@prompt.input(header: "公開FQDN", value: initial)).strip.downcase.sub(/\.\z/, "")
          raise Error, "有効なFQDNを入力してください" unless value.match?(FQDN)

          value
        end

        sig do
          params(
            current: DestinationConfig,
            proposed: T::Hash[String, T.untyped],
            destination: String
          ).void
        end
        def confirm_destination_change!(current, proposed, destination)
          before = current.managed_values
          after = managed_values(proposed)
          changed = after.keys.select { |key| before[key] != after[key] }
          @output.puts "#{destination} Kamal設定の変更:"
          changed.each { |key| @output.puts "  #{key}: #{before[key].inspect} -> #{after[key].inspect}" }
          return unless before.values.compact.any?
          return if @prompt.confirm(
            "既存の#{destination} Kamal設定を上書きしますか？",
            default: false,
            affirmative: "上書き",
            negative: "中止"
          )

          raise Error, "Kamal設定の上書きを中止しました"
        end

        sig { params(ip: String).void }
        def confirm_ssh_change!(ip)
          current = @ssh.current_config(ip)
          return if current.empty? || current == SshHardener::CONFIG

          @output.puts "#{SshHardener::CONFIG_PATH}を次の内容へ置換します:\n#{SshHardener::CONFIG}"
          return if @prompt.confirm(
            "既存の専用SSH設定を上書きしますか？",
            default: false,
            affirmative: "上書き",
            negative: "中止"
          )

          raise Error, "SSH設定の上書きを中止しました"
        end

        sig { params(data: T::Hash[String, T.untyped]).returns(T::Hash[String, T.untyped]) }
        def managed_values(data)
          DestinationConfig::MANAGED_PATHS.to_h do |path|
            value = path.reduce(T.let(data, T.untyped)) { |entry, key| entry.is_a?(Hash) ? entry[key] : nil }
            [path.join("."), value]
          end
        end

        sig { params(destination: String, config: DestinationConfig).void }
        def validate_kamal_config!(destination, config)
          command = [@root.join("bin/kamal").to_s, "config", "-d", destination]
          result = @runner.capture(command)
          return if result.success

          config.restore!
          raise Error, "Kamal設定が不正なためdestinationファイルを復元しました: #{result.stderr.strip}"
        end

        sig do
          params(
            hostname: String,
            instance: ServerInstance,
            ipv6_address: T.nilable(String)
          ).returns(T::Array[T.untyped])
        end
        def health_targets(hostname, instance, ipv6_address:)
          targets = [HealthChecker::Target.new(hostname:, address: instance.main_ip)]
          targets << HealthChecker::Target.new(hostname:, address: ipv6_address) if ipv6_address
          targets << HealthChecker::Target.new(hostname:, address: nil)
          targets
        end
      end
    end
  RUBY
  create_file "lib/deployment/server_setup.rb", server_setup, force: true

  create_file "lib/tasks/deployment.rake", <<~'RAKE', force: true
    # typed: true
    # frozen_string_literal: true

    require Rails.root.join("lib/deployment/configurator")
    require Rails.root.join("lib/deployment/server_setup")

    namespace :deployment do
      desc "デプロイ用の外部サービスと資格情報を構成する"
      task configure: :environment do
        Deployment::Configurator.new(root: Rails.root).run!
      end

      desc "Vultr VPSを選択してSSHとKamal destinationを初期設定する"
      task :"setup-server" => :environment do
        Deployment::ServerSetup.new(root: Rails.root).run!
      end
    end
  RAKE

  create_file "test/lib/deployment/configurator_test.rb", <<~'RUBY', force: true
    # typed: true
    # frozen_string_literal: true

    require "test_helper"
    require "deployment/configurator"
    require "stringio"
    require "tmpdir"

    class DeploymentConfiguratorTest < ActiveSupport::TestCase
      class FailingRunner
        attr_reader :calls

        def initialize
          @calls = []
        end

        def capture(*arguments)
          @calls << arguments
          raise "command must not run"
        end
      end

      test "uses deterministic environment-specific resource names" do
        assert_equal "my-app", Deployment::Configurator.normalized_app_id("My App!")
        assert_equal "deploy:my-app:production",
          Deployment::Configurator.service_account_name("My App!", "production")
        assert_equal "my-app-production",
          Deployment::Configurator.destination_vault_name("My App!", "production")
        assert_equal "my-app-db-production",
          Deployment::Configurator.default_bucket_name("My App!", "production")
        assert_equal "my-app-r2-production",
          Deployment::Configurator.cloudflare_token_name("My App!", "production")
        assert_operator Deployment::Configurator.default_bucket_name("a" * 100, "staging").bytesize, :<=, 63
        assert_operator Deployment::Configurator.cloudflare_token_name("a" * 200, "staging").bytesize, :<=, 120
      end

      test "rejects service account and Connect authentication before commands" do
        %w[OP_SERVICE_ACCOUNT_TOKEN OP_CONNECT_HOST OP_CONNECT_TOKEN].each do |name|
          runner = FailingRunner.new
          error = assert_raises(Deployment::Error) do
            Deployment::Configurator.new(
              prompt: Object.new,
              runner:,
              output: StringIO.new,
              environment: {
                "CLOUDFLARE_INITIAL_API_TOKEN" => "initial-token",
                name => "configured"
              }
            ).run!
          end

          assert_includes error.message, name
          assert_empty runner.calls
        end
      end

      test "missing Cloudflare initial token has no external side effects" do
        Dir.mktmpdir do |directory|
          output = StringIO.new
          runner = FailingRunner.new

          Deployment::Configurator.new(
            root: Pathname(directory),
            prompt: Object.new,
            runner:,
            output:,
            environment: {}
          ).run!

          assert_includes output.string, "CLOUDFLARE_INITIAL_API_TOKEN"
          assert_includes output.string, "Account API Tokens Write"
          assert_empty runner.calls
          assert_empty Dir.children(directory)
        end
      end

      test "requires an active human 1Password user" do
        configurator = Deployment::Configurator.new(prompt: Object.new, environment: {})
        one_password = Object.new
        configurator.instance_variable_set(:@one_password, one_password)

        one_password.define_singleton_method(:current_user) do |_account_id|
          { "id" => "service", "type" => "SERVICE_ACCOUNT", "state" => "ACTIVE" }
        end
        error = assert_raises(Deployment::Error) do
          configurator.send(:validate_human_one_password_user!, "op-account")
        end
        assert_includes error.message, "人間ユーザー"

        one_password.define_singleton_method(:current_user) do |_account_id|
          { "id" => "person", "type" => "MEMBER", "state" => "SUSPENDED" }
        end
        error = assert_raises(Deployment::Error) do
          configurator.send(:validate_human_one_password_user!, "op-account")
        end
        assert_includes error.message, "activeではありません"
      end

      test "Kamal secrets reference the human account and R2 item without the service token" do
        Dir.mktmpdir do |directory|
          root = Pathname(directory)
          Deployment::KamalSecretsWriter.new(root:, output: StringIO.new).write(
            destination: "production",
            account_id: "op-account",
            vault_id: "vault-id",
            item_id: "r2-item-id"
          )
          path = root.join(".kamal/secrets.production")
          content = path.read

          assert_equal 0o600, path.stat.mode & 0o777
          assert_includes content, "--account op-account"
          assert_includes content, "--from vault-id/r2-item-id"
          refute_includes content, "OP_SERVICE_ACCOUNT_TOKEN"
          refute_includes content, "CLOUDFLARE_R2_API_TOKEN"
        end
      end

      test "reuses an exact R2 credential pair without saving the 1Password item" do
        configurator = Deployment::Configurator.new(output: StringIO.new, environment: {})
        account_id = "cf-account"
        bucket = "sample-db-production"
        permission_group = { "id" => "r2-write" }
        policy = configurator.send(:cloudflare_token_policy, account_id, bucket, "r2-write")
        raw_token = "cloudflare-secret"
        item = {
          "id" => "r2-item",
          "title" => "sample Litestream R2 production",
          "category" => "API_CREDENTIAL",
          "fields" => [
            { "id" => "CLOUDFLARE_R2_API_TOKEN", "label" => "CLOUDFLARE_R2_API_TOKEN", "type" => "CONCEALED", "value" => raw_token },
            { "id" => "CF_ACCOUNT_ID", "label" => "CF_ACCOUNT_ID", "type" => "STRING", "value" => account_id },
            { "id" => "LITESTREAM_R2_BUCKET", "label" => "LITESTREAM_R2_BUCKET", "type" => "STRING", "value" => bucket },
            { "id" => "R2_ACCESS_KEY", "label" => "R2_ACCESS_KEY", "type" => "CONCEALED", "value" => "token-id" },
            { "id" => "R2_SECRET_KEY", "label" => "R2_SECRET_KEY", "type" => "CONCEALED", "value" => Digest::SHA256.hexdigest(raw_token) }
          ]
        }
        plan = configurator.send(
          :plan_r2_credentials,
          "production",
          account_id:,
          bucket:,
          permission_group:,
          cloudflare_tokens: [{
            "id" => "token-id",
            "name" => "sample-r2-production",
            "status" => "active",
            "policies" => [policy]
          }],
          item_plan: { "title" => item.fetch("title"), "id" => item.fetch("id"), "item" => item }
        )
        assert_equal "reuse", plan.dig("token", "action")
        assert_equal "reuse", plan.dig("item", "action")

        one_password = Object.new
        one_password.define_singleton_method(:save_item) { |*, **| raise "must not save a reused item" }
        configurator.instance_variable_set(:@one_password, one_password)
        assert_equal "r2-item", configurator.send(
          :apply_r2_item_plan,
          plan.fetch("item"),
          account_id: "op-account",
          vault_id: "vault-id",
          fields: T.cast(plan.dig("token", "credentials"), T::Hash[String, String]),
          concealed_fields: %w[CLOUDFLARE_R2_API_TOKEN R2_ACCESS_KEY R2_SECRET_KEY]
        )
      end
    end
  RUBY

  create_file "test/lib/deployment/server_setup_test.rb", <<~'RUBY', force: true
    # typed: true
    # frozen_string_literal: true

    require "test_helper"
    require "deployment/server_setup"
    require "stringio"
    require "tmpdir"

    class DeploymentServerSetupTest < ActiveSupport::TestCase
      class FakeRunner
        attr_reader :captures, :runs

        def initialize(results = [], run_result: 0)
          @results = results
          @run_result = run_result
          @captures = []
          @runs = []
        end

        def capture(command, environment: {}, stdin_data: nil)
          @captures << { command:, environment:, stdin_data: }
          @results.shift || Deployment::Result.new(stdout: "", stderr: "", success: true, exitstatus: 0)
        end

        def run(command, environment: {})
          @runs << { command:, environment: }
          @run_result
        end
      end

      class FakePrompt
        attr_reader :confirmations

        def initialize(deploy: false, destination: "production", dns_mode: "DNS-only", overwrite: true)
          @deploy = deploy
          @destination = destination
          @dns_mode = dns_mode
          @overwrite = overwrite
          @confirmations = []
        end

        def choose(values, header:, **)
          case header
          when "Kamal destination" then @destination
          when "IaaS" then "Vultr"
          when "DNS構成" then @dns_mode
          else values.first
          end
        end

        def input(**)
          "app.example.com"
        end

        def confirm(message, **options)
          @confirmations << [message, options]
          message.start_with?("Kamal setup") ? @deploy : @overwrite
        end
      end

      class FakeVultr
        attr_reader :validated

        def validate!
          @validated = true
        end

        def eligible_instances
          [Deployment::ServerInstance.new(
            id: "instance-1",
            label: "app-production",
            main_ip: "192.0.2.10",
            v6_main_ip: "2001:db8::10",
            os: "Ubuntu 24.04 LTS x64",
            region: "nrt"
          )]
        end
      end

      class FakeDns
        attr_reader :calls

        def initialize(ipv6: false)
          @ipv6 = ipv6
          @calls = []
        end

        def direct_ipv6!(_hostname, instance)
          @calls << :direct
          @ipv6 ? instance.v6_main_ip : nil
        end

        def cloudflare_proxy!(_hostname)
          @calls << :cloudflare
        end
      end

      class FakeSsh
        attr_reader :preflight, :applied, :validated

        def validate_client!
          @validated = true
        end

        def preflight!(ip, pristine:)
          @preflight = [ip, pristine]
        end

        def current_config(_ip)
          ""
        end

        def apply!(ip)
          @applied = ip
        end
      end

      class FakeHealth
        attr_reader :targets

        def initialize(fail_on_call: true)
          @fail_on_call = fail_on_call
        end

        def wait!(targets)
          @targets = targets
          raise "health must not run" if @fail_on_call
        end
      end

      test "Vultr client requires v3 and filters eligible Ubuntu instances" do
        runner = FakeRunner.new([
          Deployment::Result.new(stdout: "vultr-cli v3.8.0\n", stderr: "", success: true, exitstatus: 0),
          Deployment::Result.new(
            stdout: JSON.generate(
              "instances" => [
                instance_json.merge("id" => "stopped", "power_status" => "stopped"),
                instance_json.merge("id" => "marketplace", "app_id" => 12)
              ],
              "meta" => { "links" => { "next" => "next-page" } }
            ),
            stderr: "",
            success: true,
            exitstatus: 0
          ),
          Deployment::Result.new(
            stdout: JSON.generate(
              "instances" => [instance_json],
              "meta" => { "links" => { "next" => "" } }
            ),
            stderr: "",
            success: true,
            exitstatus: 0
          )
        ])
        client = Deployment::VultrClient.new(runner:, environment: { "VULTR_API_KEY" => "secret" })

        client.validate!
        instances = client.eligible_instances

        assert_equal ["instance-1"], instances.map(&:id)
        assert_equal ["vultr-cli", "instance", "list", "--output=json", "--per-page=500"],
          runner.captures.fetch(1).fetch(:command)
        assert_equal "--cursor=next-page", runner.captures.fetch(2).fetch(:command).last
        assert_equal({ "VULTR_API_KEY" => "secret" }, runner.captures.fetch(2).fetch(:environment))
      end

      test "Vultr client rejects missing credentials old CLI malformed JSON and no candidates" do
        runner = FakeRunner.new
        client = Deployment::VultrClient.new(runner:, environment: {})
        assert_raises(Deployment::Error) { client.validate! }
        assert_empty runner.captures

        runner = FakeRunner.new([
          Deployment::Result.new(stdout: "vultr-cli v2.0.0\n", stderr: "", success: true, exitstatus: 0)
        ])
        client = Deployment::VultrClient.new(runner:, environment: { "VULTR_API_KEY" => "secret" })
        assert_raises(Deployment::Error) { client.validate! }

        runner = FakeRunner.new([
          Deployment::Result.new(stdout: "not-json", stderr: "", success: true, exitstatus: 0)
        ])
        client = Deployment::VultrClient.new(runner:, environment: { "VULTR_API_KEY" => "secret" })
        assert_raises(Deployment::Error) { client.eligible_instances }

        runner = FakeRunner.new([
          Deployment::Result.new(
            stdout: JSON.generate("instances" => [], "meta" => { "links" => { "next" => "" } }),
            stderr: "",
            success: true,
            exitstatus: 0
          )
        ])
        client = Deployment::VultrClient.new(runner:, environment: { "VULTR_API_KEY" => "secret" })
        assert_raises(Deployment::Error) { client.eligible_instances }
      end

      test "direct DNS requires the selected IPv4 and matching optional IPv6" do
        resolver = Object.new
        resolver.define_singleton_method(:getaddresses) { |_hostname| ["192.0.2.10", "2001:db8::10"] }
        validator = Deployment::DnsValidator.new(resolver:, cloudflare_ranges: Object.new)

        assert_equal "2001:db8::10", validator.direct_ipv6!("app.example.com", instance)

        resolver.define_singleton_method(:getaddresses) { |_hostname| ["192.0.2.10"] }
        assert_nil validator.direct_ipv6!("app.example.com", instance)

        resolver.define_singleton_method(:getaddresses) { |_hostname| ["192.0.2.10", "192.0.2.11"] }
        assert_raises(Deployment::Error) { validator.direct_ipv6!("app.example.com", instance) }

        resolver.define_singleton_method(:getaddresses) { |_hostname| ["192.0.2.10", "2001:db8::11"] }
        assert_raises(Deployment::Error) { validator.direct_ipv6!("app.example.com", instance) }
      end

      test "Cloudflare proxy requires every resolved address in the official ranges" do
        resolver = Object.new
        resolver.define_singleton_method(:getaddresses) { |_hostname| ["104.16.1.2", "2606:4700::1"] }
        ranges = Object.new
        ranges.define_singleton_method(:fetch) { [IPAddr.new("104.16.0.0/13"), IPAddr.new("2606:4700::/32")] }
        validator = Deployment::DnsValidator.new(resolver:, cloudflare_ranges: ranges)

        validator.cloudflare_proxy!("app.example.com")

        resolver.define_singleton_method(:getaddresses) { |_hostname| ["192.0.2.10"] }
        assert_raises(Deployment::Error) { validator.cloudflare_proxy!("app.example.com") }
      end

      test "Cloudflare ranges loads current IPv4 and IPv6 CIDRs and rejects bad responses" do
        response = Net::HTTPOK.new("1.1", "200", "OK")
        response.instance_variable_set(
          :@body,
          JSON.generate(
            "success" => true,
            "result" => { "ipv4_cidrs" => ["104.16.0.0/13"], "ipv6_cidrs" => ["2606:4700::/32"] }
          )
        )
        response.instance_variable_set(:@read, true)
        http = Object.new
        http.define_singleton_method(:get_response) { |uri| uri == Deployment::CloudflareRanges::ENDPOINT ? response : nil }

        assert_equal [IPAddr.new("104.16.0.0/13"), IPAddr.new("2606:4700::/32")],
          Deployment::CloudflareRanges.new(http:).fetch

        http.define_singleton_method(:get_response) { |_uri| raise SocketError, "offline" }
        error = assert_raises(Deployment::Error) { Deployment::CloudflareRanges.new(http:).fetch }
        assert_includes error.message, "取得できません"
      end

      test "destination writer preserves unrelated plain YAML and writes managed values" do
        Dir.mktmpdir do |directory|
          path = Pathname(directory).join("deploy.production.yml")
          path.write(YAML.dump("deploy_timeout" => 45))
          config = Deployment::DestinationConfig.new(path)

          config.write!(config.proposed(instance:, hostname: "app.example.com", ipv6: true))
          written = YAML.safe_load(path.read)

          assert_equal 45, written.fetch("deploy_timeout")
          assert_equal ["192.0.2.10"], written.dig("servers", "web")
          assert_equal ["192.0.2.10"], written.dig("servers", "worker", "hosts") if Deployment::HAS_WORKER
          assert_equal ["0.0.0.0", "::"], written.dig("proxy", "run", "bind_ips")
          assert_equal "app.example.com", written.dig("proxy", "host")
          assert_equal "https://app.example.com", written.dig("env", "clear", "APPLICATION_ORIGIN")
          assert_equal "192.0.2.10", written.dig("accessories", "litestream", "host")
          assert_equal "root", written.dig("ssh", "user")

          config.restore!
          assert_equal YAML.dump("deploy_timeout" => 45), path.read
        end
      end

      test "destination writer rejects ERB comments and aliases" do
        ["<%= ENV.fetch(\"HOST\") %>\n", "# managed\n--- {}\n", "a: &a 1\nb: *a\n"].each do |contents|
          Dir.mktmpdir do |directory|
            path = Pathname(directory).join("deploy.production.yml")
            path.write(contents)
            assert_raises(Deployment::Error) { Deployment::DestinationConfig.new(path) }
          end
        end
      end

      test "destination writer rejects conflicting managed types and multiple hosts" do
        Dir.mktmpdir do |directory|
          path = Pathname(directory).join("deploy.production.yml")
          path.write(YAML.dump("servers" => { "web" => ["192.0.2.10", "192.0.2.11"] }))
          assert_raises(Deployment::Error) { Deployment::DestinationConfig.new(path).web_host }

          path.write(YAML.dump("proxy" => "invalid"))
          config = Deployment::DestinationConfig.new(path)
          assert_raises(Deployment::Error) { config.proposed(instance:, hostname: "app.example.com", ipv6: false) }
        end
      end

      test "SSH hardener uses a control master and verifies a new independent connection" do
        runner = FakeRunner.new
        Deployment::SshHardener.new(runner:).apply!("192.0.2.10")

        assert runner.captures.any? { |call| call.fetch(:command).include?("-M") }
        verify = runner.captures.find do |call|
          call.fetch(:command).include?("ControlPath=none") && call.fetch(:stdin_data).to_s.include?("passwordauthentication no")
        end
        assert verify
        assert_includes verify.fetch(:command), "ControlMaster=no"
        refute_includes Deployment::SshHardener::CONFIG.downcase, "ufw"
      end

      test "SSH client and preflight use fixed public key root connection options" do
        runner = FakeRunner.new([
          Deployment::Result.new(stdout: "", stderr: "OpenSSH_10.0p1", success: true, exitstatus: 0),
          Deployment::Result.new(stdout: "", stderr: "", success: true, exitstatus: 0)
        ])
        hardener = Deployment::SshHardener.new(runner:)

        hardener.validate_client!
        hardener.preflight!("192.0.2.10", pristine: true)

        command = runner.captures.fetch(1).fetch(:command)
        assert_equal "root@192.0.2.10", command.last(3).fetch(0)
        assert_includes command, "BatchMode=yes"
        assert_includes command, "PreferredAuthentications=publickey"
        assert_includes command, "StrictHostKeyChecking=accept-new"
        script = runner.captures.fetch(1).fetch(:stdin_data)
        assert_includes script, "docker ps -aq"
        assert_includes script, ":22$"
        refute_match(/\bufw\b/i, script)
      end

      test "SSH hardener restores the drop-in through the control master after apply failure" do
        runner = FakeRunner.new([
          Deployment::Result.new(stdout: "", stderr: "", success: true, exitstatus: 0),
          Deployment::Result.new(stdout: "", stderr: "reload failed", success: false, exitstatus: 1),
          Deployment::Result.new(stdout: "", stderr: "", success: true, exitstatus: 0),
          Deployment::Result.new(stdout: "", stderr: "", success: true, exitstatus: 0)
        ])

        error = assert_raises(Deployment::Error) do
          Deployment::SshHardener.new(runner:).apply!("192.0.2.10")
        end

        assert_includes error.message, "復元しました"
        rollback = runner.captures.fetch(2)
        assert_includes rollback.fetch(:command), "-S"
        assert_includes rollback.fetch(:stdin_data), "systemctl reload ssh"
      end

      test "interactive task hardens SSH and writes config without deploying when declined" do
        Dir.mktmpdir do |directory|
          root = Pathname(directory)
          root.join("config").mkpath
          root.join(".kamal").mkpath
          root.join("bin").mkpath
          root.join("config/deploy.production.yml").write("--- {}\n")
          root.join("config/deploy.staging.yml").write("--- {}\n")
          root.join(".kamal/secrets.production").write("RAILS_MASTER_KEY=x\n")
          output = StringIO.new
          runner = FakeRunner.new
          ssh = FakeSsh.new
          vultr = FakeVultr.new
          prompt = FakePrompt.new(deploy: false)

          Deployment::ServerSetup.new(
            root:,
            prompt:,
            runner:,
            output:,
            environment: { "VULTR_API_KEY" => "secret" },
            terminal: true,
            vultr:,
            dns: FakeDns.new,
            ssh:,
            health: FakeHealth.new
          ).run!

          written = YAML.safe_load(root.join("config/deploy.production.yml").read)
          assert vultr.validated
          assert ssh.validated
          assert_equal ["192.0.2.10", true], ssh.preflight
          assert_equal "192.0.2.10", ssh.applied
          assert_equal ["192.0.2.10"], written.dig("servers", "web")
          assert_empty runner.runs
          assert_includes output.string, "bin/kamal setup -d production"
          final_confirmation = prompt.confirmations.fetch(-1)
          assert_equal true, final_confirmation.fetch(1).fetch(:default)
        end
      end

      test "task rejects a production and staging IP collision before changing SSH or YAML" do
        with_root(staging: YAML.dump("servers" => { "web" => ["192.0.2.10"] })) do |root|
          ssh = FakeSsh.new
          original = root.join("config/deploy.production.yml").read

          error = assert_raises(Deployment::Error) do
            run_setup(root:, ssh:, prompt: FakePrompt.new)
          end

          assert_includes error.message, "stagingで使用"
          assert_nil ssh.preflight
          assert_nil ssh.applied
          assert_equal original, root.join("config/deploy.production.yml").read
        end
      end

      test "same destination rerun skips the pristine VPS requirement" do
        with_root(production: YAML.dump("servers" => { "web" => ["192.0.2.10"] })) do |root|
          ssh = FakeSsh.new

          run_setup(root:, ssh:, prompt: FakePrompt.new(deploy: false))

          assert_equal ["192.0.2.10", false], ssh.preflight
          assert_equal "192.0.2.10", ssh.applied
        end
      end

      test "declining destination overwrite keeps SSH and YAML unchanged" do
        original = YAML.dump("servers" => { "web" => ["192.0.2.20"] })
        with_root(production: original) do |root|
          ssh = FakeSsh.new
          prompt = FakePrompt.new(overwrite: false)

          assert_raises(Deployment::Error) { run_setup(root:, ssh:, prompt:) }

          assert_equal ["192.0.2.10", true], ssh.preflight
          assert_nil ssh.applied
          assert_equal original, root.join("config/deploy.production.yml").read
          overwrite = prompt.confirmations.find { |message, _options| message.include?("Kamal設定を上書き") }
          assert_equal false, overwrite.fetch(1).fetch(:default)
        end
      end

      test "invalid merged Kamal config restores YAML but keeps successful SSH hardening" do
        failure = Deployment::Result.new(stdout: "", stderr: "invalid config", success: false, exitstatus: 1)
        with_root do |root|
          ssh = FakeSsh.new
          original = root.join("config/deploy.production.yml").read

          error = assert_raises(Deployment::Error) do
            run_setup(root:, ssh:, runner: FakeRunner.new([failure]), prompt: FakePrompt.new)
          end

          assert_includes error.message, "destinationファイルを復元"
          assert_equal "192.0.2.10", ssh.applied
          assert_equal original, root.join("config/deploy.production.yml").read
        end
      end

      test "failed Kamal setup preserves destination and prints the exact retry command" do
        with_root do |root|
          runner = FakeRunner.new([], run_result: 1)

          error = assert_raises(Deployment::Error) do
            run_setup(root:, runner:, prompt: FakePrompt.new(deploy: true))
          end

          assert_includes error.message, "bin/kamal setup -d production"
          assert_equal [root.join("bin/kamal").to_s, "setup", "-d", "production"],
            runner.runs.fetch(0).fetch(:command)
          assert_equal ["192.0.2.10"], YAML.safe_load(root.join("config/deploy.production.yml").read).dig("servers", "web")
        end
      end

      test "successful Cloudflare setup verifies the IPv4 origin and public URL" do
        with_root do |root|
          dns = FakeDns.new
          health = FakeHealth.new(fail_on_call: false)
          runner = FakeRunner.new

          run_setup(
            root:,
            runner:,
            dns:,
            health:,
            prompt: FakePrompt.new(deploy: true, dns_mode: "Cloudflare proxy")
          )

          assert_equal [:cloudflare], dns.calls
          assert_equal ["192.0.2.10", nil], health.targets.map(&:address)
          assert_equal 1, runner.runs.length
        end
      end

      private

      def with_root(production: "--- {}\n", staging: "--- {}\n")
        Dir.mktmpdir do |directory|
          root = Pathname(directory)
          root.join("config").mkpath
          root.join(".kamal").mkpath
          root.join("bin").mkpath
          root.join("config/deploy.production.yml").write(production)
          root.join("config/deploy.staging.yml").write(staging)
          root.join(".kamal/secrets.production").write("RAILS_MASTER_KEY=x\n")
          yield root
        end
      end

      def run_setup(
        root:,
        prompt:,
        runner: FakeRunner.new,
        dns: FakeDns.new,
        ssh: FakeSsh.new,
        health: FakeHealth.new
      )
        Deployment::ServerSetup.new(
          root:,
          prompt:,
          runner:,
          output: StringIO.new,
          environment: { "VULTR_API_KEY" => "secret" },
          terminal: true,
          vultr: FakeVultr.new,
          dns:,
          ssh:,
          health:
        ).run!
      end

      def instance
        Deployment::ServerInstance.new(
          id: "instance-1",
          label: "app-production",
          main_ip: "192.0.2.10",
          v6_main_ip: "2001:db8::10",
          os: "Ubuntu 24.04 LTS x64",
          region: "nrt"
        )
      end

      def instance_json
        {
          "id" => "instance-1",
          "label" => "app-production",
          "main_ip" => "192.0.2.10",
          "v6_main_ip" => "2001:db8::10",
          "os" => "Ubuntu 24.04 LTS x64",
          "region" => "nrt",
          "status" => "active",
          "power_status" => "running",
          "server_status" => "ok",
          "app_id" => 0
        }
      end
    end
  RUBY
end

def configure_kamal
  app_id = PLAN.fetch("app_id")
  databases = [
    { "name" => "primary", "path" => "/rails/storage/production.sqlite3" },
    { "name" => "storage", "path" => "/rails/storage/production_storage.sqlite3" }
  ]
  if VALUES.fetch("active_job") == "solid_queue"
    databases << { "name" => "queue", "path" => "/rails/storage/production_queue.sqlite3" }
  end
  if VALUES.fetch("action_cable") == "solid_cable"
    databases << { "name" => "cable", "path" => "/rails/storage/production_cable.sqlite3" }
  end

  litestream_config = {
    "socket" => {
      "enabled" => true,
      "path" => "/rails/storage/.litestream.sock",
      "permissions" => "0660"
    },
    "dbs" => databases.map do |database|
      {
        "path" => database.fetch("path"),
        "restore-if-db-not-exists" => true,
        "replica" => {
          "type" => "s3",
          "bucket" => "$" + "{LITESTREAM_R2_BUCKET}",
          "path" => database.fetch("name"),
          "endpoint" => "$" + "{CF_ACCOUNT_ID}.r2.cloudflarestorage.com",
          "region" => "auto",
          "access-key-id" => "$" + "{R2_ACCESS_KEY}",
          "secret-access-key" => "$" + "{R2_SECRET_KEY}"
        }
      }
    end
  }
  create_file "config/litestream.yml", YAML.dump(litestream_config, line_width: -1), force: true

  common_secret_names = %w[RAILS_MASTER_KEY]
  common_secret_names.concat(%w[VAPID_PUBLIC_KEY VAPID_PRIVATE_KEY VAPID_SUBJECT]) if VALUES.fetch("web_push") == "use"
  kamal_secrets = common_secret_names.map do |name|
    if name == "RAILS_MASTER_KEY"
      "RAILS_MASTER_KEY=$(cat config/master.key)"
    else
      "#{name}=$" + "{#{name}:?#{name} is required}"
    end
  end
  remove_file ".kamal/secrets"
  create_file ".kamal/secrets-common", kamal_secrets.join("\n") + "\n", force: true

  worker_role = if VALUES.fetch("active_job") == "solid_queue"
    "  worker:\n    cmd: bin/jobs --mode async\n"
  else
    ""
  end
  accessory_secret_lines = %w[CF_ACCOUNT_ID LITESTREAM_R2_BUCKET R2_ACCESS_KEY R2_SECRET_KEY]
    .map { |name| "        - #{name}" }.join("\n")
  vapid_secret_lines = if VALUES.fetch("web_push") == "use"
    "    - VAPID_PUBLIC_KEY\n    - VAPID_PRIVATE_KEY\n    - VAPID_SUBJECT\n"
  else
    ""
  end
  create_file "config/deploy.yml", <<~YAML, force: true
    service: #{app_id}
    image: #{app_id}
    minimum_version: 2.11.0
    require_destination: true
    primary_role: web

    servers:
      web: []
    #{worker_role}
    proxy:
      ssl: true
      app_port: 80
      healthcheck:
        path: /up

    registry:
      server: localhost:5555

    builder:
      arch: <%= ENV.fetch("KAMAL_BUILD_ARCH", "amd64") %>

    env:
      secret:
        - RAILS_MASTER_KEY
    #{vapid_secret_lines}
    volumes:
      - "#{app_id}_<%= ENV.fetch(\"KAMAL_DESTINATION\") %>_storage:/rails/storage"

    asset_path: /rails/public/assets

    accessories:
      litestream:
        image: litestream/litestream:0.5.15
        cmd: replicate -config /etc/litestream.yml
        files:
          - config/litestream.yml:/etc/litestream.yml
        volumes:
          - "#{app_id}_<%= ENV.fetch(\"KAMAL_DESTINATION\") %>_storage:/rails/storage"
        env:
          secret:
    #{accessory_secret_lines}
        options:
          user: "1000:1000"
  YAML
  create_file "config/deploy.production.yml", "--- {}\n", force: true
  create_file "config/deploy.staging.yml", "--- {}\n", force: true
  create_file ".dockerignore", <<~IGNORE, force: true
    .git
    .kamal
    log/*
    tmp/*
    storage/*
    node_modules
    config/master.key
    mise.local.toml
  IGNORE

  docker_build_packages = %w[build-essential git nodejs npm pkg-config libsqlite3-dev libyaml-dev]
  if VALUES.fetch("additional_login_methods").include?("siwe")
    docker_build_packages.concat(%w[autoconf automake libffi-dev libgmp-dev libssl-dev libtool python3-dev])
  end

  create_file "Dockerfile", format(<<~'DOCKERFILE', build_packages: docker_build_packages.join(" ")), force: true
    # syntax=docker/dockerfile:1
    # check=error=true
    ARG RUBY_VERSION=4.0.0
    FROM ruby:${RUBY_VERSION}-slim AS base
    WORKDIR /rails
    RUN apt-get update -qq && \
        apt-get install --no-install-recommends -y ca-certificates curl libjemalloc2 libsqlite3-0 libvips && \
        rm -rf /var/lib/apt/lists /var/cache/apt/archives
    ENV RAILS_ENV=production \
        BUNDLE_DEPLOYMENT=1 \
        BUNDLE_PATH=/usr/local/bundle \
        BUNDLE_WITHOUT=development:test \
        LD_PRELOAD=libjemalloc.so.2 \
        RUBY_YJIT_ENABLE=1

    FROM base AS build
    RUN apt-get update -qq && \
        apt-get install --no-install-recommends -y %{build_packages} && \
        rm -rf /var/lib/apt/lists /var/cache/apt/archives
    COPY Gemfile Gemfile.lock ./
    RUN bundle install && rm -rf /root/.bundle
    COPY package.json package-lock.json ./
    RUN npm ci
    COPY . .
    RUN APPLICATION_ORIGIN=https://build.example.com SECRET_KEY_BASE_DUMMY=1 bundle exec rails assets:precompile && \
        rm -rf node_modules

    FROM base
    RUN groupadd --system --gid 1000 rails && \
        useradd rails --uid 1000 --gid 1000 --create-home --shell /bin/bash
    COPY --chown=rails:rails --from=build /usr/local/bundle /usr/local/bundle
    COPY --chown=rails:rails --from=build /rails /rails
    USER 1000:1000
    EXPOSE 80
    ENTRYPOINT ["/rails/bin/docker-entrypoint"]
    CMD ["./bin/thrust", "./bin/rails", "server"]
  DOCKERFILE

  create_file "bin/docker-entrypoint", <<~'SH', force: true
    #!/bin/bash
    set -euo pipefail

    if [[ "${1:-}" == "./bin/thrust" && "${2:-}" == "./bin/rails" && "${3:-}" == "server" ]]; then
      /rails/bin/wait-for-litestream
      ./bin/rails db:prepare
    elif [[ "${1:-}" == "bin/jobs" || "${1:-}" == "./bin/jobs" ]]; then
      /rails/bin/wait-for-litestream
    fi

    exec "$@"
  SH
  chmod "bin/docker-entrypoint", 0o755

  create_file "bin/wait-for-litestream", <<~'RUBY', force: true
    #!/usr/bin/env ruby
    require "socket"
    require "timeout"

    socket_path = "/rails/storage/.litestream.sock"
    begin
      Timeout.timeout(Integer(ENV.fetch("LITESTREAM_READY_TIMEOUT", "60"))) do
        loop do
          begin
            UNIXSocket.open(socket_path) do |socket|
              socket.write("GET /status HTTP/1.0\r\nHost: localhost\r\n\r\n")
              exit 0 if socket.gets&.match?(/\AHTTP\/1\.[01] 200\b/)
            end
          rescue Errno::ENOENT, Errno::ECONNREFUSED
            nil
          end
          sleep 1
        end
      end
    rescue Timeout::Error
      warn "Litestream did not become ready at #{socket_path}"
      exit 1
    end
  RUBY
  chmod "bin/wait-for-litestream", 0o755

  configure_deployment(app_id)
  configure_kamal_restore(app_id, databases)
  configure_kamal_maintenance(app_id, databases)

  create_file ".kamal/hooks/pre-deploy", <<~SH, force: true
    #!/bin/sh
    set -eu
    : "\${KAMAL_DESTINATION:?KAMAL_DESTINATION is required}"
    restore_marker=".kamal/#{app_id}-\${KAMAL_DESTINATION}-restore-in-progress"
    maintenance_marker=".kamal/#{app_id}-\${KAMAL_DESTINATION}-maintenance.json"
    if ! bin/kamal server exec "test ! -e \$restore_marker" -d "\$KAMAL_DESTINATION"; then
      echo "#{app_id} (\$KAMAL_DESTINATION): database restore is in progress; deploy aborted" >&2
      exit 1
    fi
    if ! bin/kamal server exec "test ! -e \$maintenance_marker" -d "\$KAMAL_DESTINATION"; then
      echo "#{app_id} (\$KAMAL_DESTINATION): maintenance mode is active; deploy aborted" >&2
      exit 1
    fi
  SH
  chmod ".kamal/hooks/pre-deploy", 0o755

  database_rows = databases.map do |database|
    "| #{database.fetch("name")} | `#{database.fetch("path")}` | `#{database.fetch("name")}` |"
  end.join("\n")
  create_file "docs/deployment.md", <<~MARKDOWN, force: true
    # Kamal, Cloudflare R2, and SQLite recovery

    This application requires the `production` or `staging` Kamal destination. Each destination
    uses its own Docker volume, Cloudflare R2 bucket, and bucket-scoped R2 API token. Web, the
    optional Solid Queue worker, and Litestream 0.5.15 share that destination's volume on one Linux
    host. Multiple deployment hosts and network filesystems are outside the supported topology.

    ## Deployment service configuration

    Install dependencies, sign in to both Wrangler and 1Password CLI as a human user, set
    `CLOUDFLARE_INITIAL_API_TOKEN`, and run:

        bin/rails deployment:configure

    `OP_SERVICE_ACCOUNT_TOKEN`, `OP_CONNECT_HOST`, and `OP_CONNECT_TOKEN` must be unset. The task
    lets you select a 1Password account, verifies that its current user is active and is not a
    service account, and passes that account ID to every 1Password operation.

    Production and staging are selected initially. For each selected destination, the task scans
    every vault in the selected account for the exact name `<normalized-app-id>-<destination>`.
    It plans creation when no vault exists, reuses the unique match by ID, and stops before any
    change when duplicates exist. It also inspects the environment-specific service account token
    item, R2 credential item, R2 bucket, and Cloudflare API token. It prints the complete plan and
    makes no changes unless you accept one default-No confirmation.

    After confirmation, the task creates any missing vault and an environment-specific service
    account named `deploy:<normalized-app-id>:<destination>`. The account has no expiration and
    receives only `read_items` for that destination's vault; it cannot create vaults or write items.
    Its one-time token is stored as a concealed `OP_SERVICE_ACCOUNT_TOKEN` field in a separate API
    Credential item with the same name. An existing unique, active item with that field is treated
    as the existing service account; the task does not authenticate with its token or recreate it.
    Duplicate, archived, or incomplete items stop configuration.

    As a Super Administrator of the target Cloudflare account, create an account-owned Initial
    Token with only dashboard permission **Account API Tokens: Edit**, named **Account API Tokens
    Write** by the API. Confirm the target account and permission on the dashboard summary before
    creating it. The task never stores this Initial Token. If it is absent, the task prints a
    prefilled Token Template URL and Cloudflare documentation, then exits before running commands
    or changing external resources or repository files.

    After selecting the Wrangler account, the task verifies that the Initial Token is active,
    belongs to that account, and has exactly that one permission for that account. Authentication,
    account, status, or policy mismatches stop before creating a vault, service account, R2 bucket,
    or repository file. Default bucket names are `<normalized-app-id>-db-production` and
    `<normalized-app-id>-db-staging`; you can change them before confirmation.

    For each destination, the task resolves the current Cloudflare permission group ID and creates
    an account-owned token named `<normalized-app-id>-r2-<destination>`. Its only allow policy is
    **Workers R2 Storage Bucket Item Write** for that destination's bucket. Names longer than 120
    bytes shorten the app ID and include its SHA-256 hash. The task lists every page of existing
    account tokens before deciding whether to create one. It creates a token and item only when
    neither exists. It reuses both only when the token name, active state, policy, bucket, and the
    1Password API Credential category plus all five managed field types and values match. An exact
    pair is shown as existing, keeps the current item ID, and does not call `op item edit`.
    Duplicate, inactive, mismatched, or one-sided token/item states stop configuration without
    automatic creation, overwrite, rotation, revocation, or deletion.

    The Cloudflare token value is stored as the concealed `CLOUDFLARE_R2_API_TOKEN` field only in
    the destination vault's `#{app_id} Litestream R2 <destination>` item. `R2_ACCESS_KEY` is the
    Cloudflare token ID; `R2_SECRET_KEY` is the SHA-256 digest of the token value. If saving either
    the service account token or Cloudflare token fails, the task re-fetches the same-named item to
    reconcile an ambiguous success before retrying. Only when you stop retrying and accept a second
    default-No confirmation are unsaved values printed once to `/dev/tty` for manual storage.
    Secrets are never placed in argv, normal output, or repository files.

    Generated `.kamal/secrets.production` and `.kamal/secrets.staging` use the selected human
    1Password account ID, destination vault ID, and R2 item ID to fetch only `CF_ACCOUNT_ID`,
    `LITESTREAM_R2_BUCKET`, `R2_ACCESS_KEY`, and `R2_SECRET_KEY` through Kamal's standard
    1Password adapter. They do not fetch either `OP_SERVICE_ACCOUNT_TOKEN` or
    `CLOUDFLARE_R2_API_TOKEN`.

    For GitHub Actions or another automated deployer, copy the token from the
    `deploy:<normalized-app-id>:<destination>` item into that environment's secret store and expose
    it as `OP_SERVICE_ACCOUNT_TOKEN` only to deployment jobs. Production and staging tokens are
    intentionally separate and can read only their own vault. This task does not configure CI.

    If migrating from the former shared `dev:<normalized-app-id>` service account, disable that
    account manually in the 1Password administration UI after the two environment-specific tokens
    are installed and verified. Automatic migration, token rotation, and old-account revocation are
    intentionally not performed. If service account creation succeeds but its token response is
    missing, do not rerun creation; inspect 1Password manually and resolve the incomplete account
    before retrying configuration.

    | Database | Local path | R2 object prefix |
    | --- | --- | --- |
    #{database_rows}

    ## Setup and routine operations

    Complete `bin/rails deployment:configure` first. Then install `vultr-cli` major v3, export a
    non-empty `VULTR_API_KEY`, ensure your existing OpenSSH configuration can authenticate to the
    target as `root` with a public key, and run:

        bin/rails deployment:setup-server

    The task requires a TTY and uses Gum to select one destination, Vultr, an eligible active
    Ubuntu LTS x64 VPS, its public FQDN, and either DNS-only or Cloudflare proxy DNS. It accepts
    only instances with a public IPv4 address, healthy running state, and no Vultr Marketplace
    application. Production and staging cannot share an IPv4 address. A newly assigned server
    must have no Docker containers and no public TCP listener other than SSH on port 22.

    DNS-only mode requires the FQDN's only A record to be the selected IPv4. An AAAA record is
    allowed only when it is the selected instance's public IPv6. Cloudflare proxy mode fetches
    Cloudflare's current public CIDRs from the unauthenticated Cloudflare IP API and requires every
    public DNS response to belong to those ranges; it does not claim to verify the hidden origin
    before setup.

    SSH connects as `root` on port 22 with public-key-only batch authentication and
    `StrictHostKeyChecking=accept-new`. The task writes
    `/etc/ssh/sshd_config.d/99-rapid-rails-template.conf`, disables password and
    keyboard-interactive authentication for all users, validates the effective sshd settings, and
    proves a separate new public-key connection before closing its recovery connection. It restores
    the previous drop-in if validation fails. It does not inspect or modify UFW, a Vultr Firewall
    Group, OS updates, or Docker directly.

    After SSH succeeds, the task atomically updates only its managed keys in
    `config/deploy.<destination>.yml`, preserving other plain YAML values. Files containing ERB,
    comments, or YAML anchors are rejected rather than reformatted. Existing managed values and an
    existing differing SSH drop-in each require a default-No confirmation. The final default-Yes
    confirmation runs `bin/kamal setup -d DESTINATION` with live output. Successful setup must also
    return HTTPS 200 from `/up` within 60 seconds. Direct DNS checks the public route and configured
    IPv4/IPv6 origins; Cloudflare proxy checks both the selected IPv4 origin with FQDN SNI and the
    public proxied route.

    Declining the final confirmation leaves the verified SSH and destination configuration in place
    and prints the manual setup command. A failed Kamal setup or HTTPS check also preserves those
    settings and exits with an error so the same command can be retried. Reassigning an existing
    destination never stops or deletes the old VPS.

    Run routine deploys as `mise exec -- bin/kamal deploy -d DESTINATION`. Set `KAMAL_BUILD_ARCH`
    only when the host architecture is not `amd64`. Litestream restores a database only when its
    local file does not exist. A replica with no backup is treated as a new database; every other
    restore or replication error prevents the application from becoming ready.

    Accessories are not replaced by a normal application deploy. After changing the Litestream
    image, configuration, files, or secrets, run
    `mise exec -- bin/kamal accessory reboot litestream -d DESTINATION`.
    Include `-d production` or `-d staging` in every Kamal operation. The application entrypoint
    waits for the Litestream control socket before `db:prepare` or the Solid Queue worker starts.

    ## Soft maintenance

    Use `/admin/soft_maintenance` when Rails and its primary database should keep running while
    new site or API requests return 503. The site and API switches are independent. Site
    maintenance still allows administrators, login and logout, static assets, Active Storage,
    PWA endpoints, and `/up`; API maintenance rejects all credentials before Bearer
    authentication. Workers, scheduled work, Maintenance Tasks, routine deploys, and requests
    already in progress continue. The saved message is shared by the site and API response.

    ## Hard maintenance

    Use the generated Rails-independent command when database maintenance must exclude every
    managed application process. Its name and command-line contract are unchanged, and its state
    and message do not synchronize with soft maintenance:

        bin/kamal-maintenance start --destination=production
        bin/kamal-maintenance status --destination=production
        bin/kamal-maintenance message --destination=production --message="Maintenance continues"
        bin/kamal-maintenance finish --destination=production

    `start` and `message` also accept `--message=TEXT`. Without it, Gum prompts with the default
    message for the application's generated locale. Messages must be non-empty, single-line plain
    text of at most 500 characters. `start`, `message`, and `finish` require a TTY and one Gum
    confirmation whose default is cancel; there is no force or noninteractive option.

    `start` first enables the Kamal Proxy 503 response, then stops every application role using
    Kamal's configured drain timeout (30 seconds by default). It verifies that Web and the optional
    Worker stopped, performs a final Litestream sync for primary, storage, and the optional queue
    and cable databases, stops Litestream, and verifies both the stopped processes and the public
    503 response. Solid Cache becomes inaccessible when the application roles stop, but remains
    intentionally outside Litestream backup and restore.

    The destination-specific remote JSON state records the phase, message, timestamps, last
    successful step, and any failed step. A failed `start` or `finish` keeps the marker and public
    maintenance response. Inspect it with `status`, fix the reported cause, and rerun the same
    subcommand to continue from the last successful step. `status` uses only Kamal, Docker state,
    and the public HTTP response; it does not boot Rails or open a database. It exits unsuccessfully
    when the marker, processes, and public response disagree.

    `finish` starts Litestream, confirms its control socket, starts Web and the optional Worker,
    checks `/up` inside Web, sends `app live`, verifies public `/up`, and only then removes the
    marker. A failure after `app live` immediately restores the maintenance response. Restore and
    maintenance markers are mutually exclusive, and the generated `pre-deploy` hook rejects normal
    deploys while either exists.

    Kamal waits for graceful process shutdown before forcing remaining Web or Worker containers to
    stop. Interrupted jobs are not retried by this command. After maintenance, recover ordinary
    Solid Queue jobs manually in Mission Control Jobs when that feature is enabled, and recover
    Maintenance Tasks from their dedicated administration screen when that feature is enabled.
    Database commands intentionally run by the operator during the maintenance window are outside
    this process-access guarantee.

    ## Manual restore

    Preview the latest available restore without changing a destination:

        mise exec -- bin/kamal-restore --destination=production --plan

    Preview or restore a point in time:

        mise exec -- bin/kamal-restore --destination=staging --plan --timestamp=2026-08-16T00:00:00Z
        mise exec -- bin/kamal-restore --destination=staging --timestamp=2026-08-16T00:00:00Z

    `--destination=production|staging` is mandatory. Omitting `--timestamp` restores the latest
    available state. A write operation requires a TTY and an exact phrase containing the application
    ID, destination, and target. There is no
    confirmation bypass or force option. All replicated databases are restored and fully checked
    before any current database is replaced.

    A successful restore prints an operation ID and retains the previous database files, including
    WAL, SHM, and journal sidecars, under `/rails/storage/.restore/OPERATION_ID/previous`.
    Roll back with:

        mise exec -- bin/kamal-restore --destination=production --rollback=OPERATION_ID

    Rollback also requires an exact typed confirmation. Retained restore directories are never
    deleted automatically. Remove one only after separately confirming that both the restored
    application and its remote replicas are correct.

    During restore, a destination-specific remote marker makes the generated `pre-deploy` hook
    reject new deployments for that destination. Restore refuses to start while maintenance state
    exists, and maintenance refuses to start while the restore marker exists. The destructive file
    switch runs while the Kamal deploy lock is held. If startup fails after the switch, services
    remain stopped and the marker remains present for inspection.
  MARKDOWN
  append_to_file "README.md", "\n## Deployment, maintenance, and recovery\n\nUse the admin soft-maintenance settings to stop site or API requests while Rails stays available. Use `bin/kamal-maintenance` for hard maintenance that stops application processes around exclusive database work. See [docs/deployment.md](docs/deployment.md) for both modes, Kamal, Litestream, and confirmed restore operations.\n"
end

